INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Gildas','El pintxo más antiguo de San Sebastián: una brocheta de anchoa en vinagre, guindilla y aceituna, servida en la barra desde los años 40.','10 min',10,'Fácil',4,'Vasca','entrante','El nombre viene de la película \'Gilda\' con Rita Hayworth: el pintxo es \'salado, verde y un poco picante\', como la protagonista. No lo prepares con mucha antelación: pierde gracia si las guindillas reblandecen la anchoa.','https://commons.wikimedia.org/wiki/Special:FilePath/Gildas_en_Donostia.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'12 anchoas en vinagre (boquerones)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'12 guindillas verdes encurtidas (piparras)',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'12 aceitunas verdes deshuesadas (manzanilla)',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Palillos de madera',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Un chorrito de aceite de oliva virgen extra',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Escurrir bien las anchoas, las guindillas y las aceitunas para que no suelten líquido en el plato.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Ensartar en cada palillo, en este orden, una aceituna, una guindilla doblada en zigzag y una anchoa enrollada.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Colocar en una fuente y rociar con un hilo de aceite de oliva justo antes de servir.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir bien frías, acompañadas de un vermut o un txakoli.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Croquetas de jamón','La croqueta cremosa de bechamel espesa y jamón picado, reina indiscutible de cualquier barra de pintxos vasca.','1 h + reposo',60,'Media',4,'Vasca','entrante','Una masa demasiado líquida es el error más común: cuanto más tiempo de reposo en frío, mejor se manejará la croqueta al formarla.','https://live.staticflickr.com/6027/5921994869_9e1cb04ee9_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'100 g de mantequilla',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'100 g de harina',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 litro de leche entera',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de jamón serrano picado fino',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla pequeña picada',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Nuez moscada, sal y pimienta',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 huevos',6);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Pan rallado',7);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva para freír',8);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sofreír la cebolla en la mantequilla hasta que esté transparente.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el jamón picado y rehogar un minuto.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar la harina y cocinar 2-3 minutos sin dejar de remover, sin que coja color.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Verter la leche caliente poco a poco, sin dejar de remover, hasta obtener una bechamel espesa y lisa. Cocinar 10 minutos a fuego suave.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sazonar con nuez moscada, sal y pimienta. Extender en una fuente, cubrir con film a piel y enfriar mínimo 4 horas (mejor de un día para otro).',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Formar las croquetas, pasarlas por huevo batido y pan rallado.',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Freír en aceite bien caliente hasta que estén doradas. Escurrir sobre papel absorbente.',6);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Tortilla de patatas','Servida en pequeñas porciones sobre pan, es uno de los pintxos fijos de cualquier barra vasca, con cebolla o sin ella según la casa.','45 min',45,'Media',6,'Vasca','entrante','El punto vasco clásico es jugoso por dentro: retira la sartén del fuego un poco antes de lo que creas necesario, el calor residual termina de cuajarla.','https://upload.wikimedia.org/wikipedia/commons/c/c0/Tortilla_de_Patatas_%28Corte_transversal%29.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 kg de patatas',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 cebollas medianas',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'8 huevos',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pelar y cortar las patatas en láminas finas. Cortar la cebolla en juliana.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Freír patatas y cebolla juntas a fuego medio-bajo en abundante aceite, removiendo de vez en cuando, hasta que estén tiernas pero no doradas (unos 20 minutos).',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Escurrir bien el aceite y mezclar con los huevos batidos y una pizca de sal. Dejar reposar 5 minutos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cuajar en una sartén antiadherente con un poco de aceite, a fuego medio, dando la vuelta con ayuda de un plato para cuajar el otro lado.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar reposar unos minutos antes de cortar en porciones.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Rabas (calamares a la romana)','Tiras de calamar rebozadas y fritas, crujientes por fuera y tiernas por dentro, típicas de los bares del Casco Viejo de Bilbao.','25 min',25,'Fácil',4,'Vasca','entrante','No sobrecargues la sartén: si añades mucho calamar de golpe, el aceite baja de temperatura y el rebozado queda blando en vez de crujiente.','https://upload.wikimedia.org/wikipedia/commons/7/74/Calamares_Romana_0984.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'600 g de calamar limpio, cortado en aros o tiras',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de harina',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva suave para freír',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 limón',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Secar bien el calamar con papel absorbente.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Salar ligeramente y pasar por harina, sacudiendo el exceso.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Freír en abundante aceite muy caliente, en tandas pequeñas, durante 1-2 minutos hasta que estén dorados.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Escurrir sobre papel absorbente y servir de inmediato con una rodaja de limón.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pimientos del piquillo rellenos de bacalao','Pimientos asados de Lodosa rellenos de una farsa de bacalao desmigado, bañados en su propia salsa.','1 h',60,'Media',4,'Vasca','entrante','Reserva el líquido de los pimientos de bote: es la base perfecta para la salsa y aporta ese punto ligeramente dulce característico del piquillo.','https://live.staticflickr.com/3126/3151073533_f80a6ffd6c_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'16 pimientos del piquillo asados (de bote o frescos asados)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'400 g de bacalao desalado desmigado',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla picada',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 dientes de ajo',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 ml de nata líquida',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Harina (opcional, para la salsa)',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pochar la cebolla y el ajo picados en aceite de oliva a fuego suave hasta que estén tiernos.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el bacalao desmigado y rehogar 5 minutos hasta que pierda el aspecto crudo.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Triturar la mitad de la mezcla con un poco de nata para ligar el relleno; mezclar con el resto sin triturar para dar textura.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Rellenar con cuidado los pimientos con una cuchara o manga pastelera.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Colocar en una cazuela, cubrir con una salsa ligera hecha con el jugo de los pimientos y el resto de la nata, y calentar a fuego suave 10 minutos sin que hierva con fuerza.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Revuelto de perretxikos','Revuelto suave con perretxikos (setas de San Jorge), muy apreciado en primavera en los caseríos vascos.','20 min',20,'Fácil',4,'Vasca','entrante','El revuelto perfecto se retira del fuego cuando aún parece un poco crudo: sigue cuajando fuera por el calor residual de la sartén.','https://live.staticflickr.com/2290/5799378172_166bcc57f7_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'400 g de perretxikos (o setas de temporada)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'8 huevos',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 dientes de ajo',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Perejil picado (opcional)',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Limpiar las setas con un paño húmedo, sin lavarlas en exceso, y trocearlas si son grandes.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Saltear el ajo picado en aceite de oliva y añadir las setas, cocinando a fuego medio hasta que suelten su agua y esta se evapore.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Salar y añadir los huevos ligeramente batidos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cuajar a fuego suave, removiendo despacio con una espátula de madera, hasta que el huevo esté cremoso pero no líquido.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir de inmediato, espolvoreado con perejil si se desea.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Bacalao al pil-pil','El plato más emblemático de la cocina vasca: bacalao confitado en aceite de oliva que se liga, sin ningún ligante añadido, en una salsa untuosa gracias a la propia gelatina del pescado.','50 min',50,'Alta',4,'Vasca','principal','La temperatura es la clave de todo: si el aceite está demasiado caliente, la gelatina se corta y la salsa nunca ligará. Ve con paciencia, a fuego bajo.','https://upload.wikimedia.org/wikipedia/commons/f/ff/Bacalao_al_Pil_Pil_%28Vizcaya%29.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 lomos de bacalao desalado, con piel',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 ml de aceite de oliva virgen extra',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 dientes de ajo laminados',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1-2 guindillas secas',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Calentar el aceite en una cazuela de barro a fuego suave y dorar los ajos laminados junto con la guindilla; retirar y reservar.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar templar el aceite antes de añadir el bacalao, con la piel hacia arriba.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocinar a fuego muy bajo entre 15 y 20 minutos, moviendo la cazuela con un ligero vaivén (sin remover con cuchara) para que el pescado suelte su gelatina.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Retirar los lomos con cuidado y reservar. Colar el aceite en un bol.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Ir añadiendo el aceite templado poco a poco sobre el jugo de la cazuela, moviendo en círculos o con la ayuda de un colador chino, hasta que emulsione y espese en una salsa untuosa (el pil-pil).',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Devolver el bacalao a la cazuela, napar con la salsa y decorar con los ajos y la guindilla reservados.',5);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Bacalao a la vizcaína','Bacalao bañado en una salsa densa de pimientos choriceros y cebolla, larga cocción, muy propia de las mesas de Bilbao en Navidad.','1 h 30 min',90,'Media',4,'Vasca','principal','Cuanto más lenta sea la cocción de la cebolla, más profunda y dulce quedará la salsa: no tengas prisa en este paso, es el alma del plato.','https://upload.wikimedia.org/wikipedia/commons/0/0b/Bacalao_Vizcaina_%28Marug%C3%A1n%29.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 lomos de bacalao desalado',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'6 pimientos choriceros (o ñoras)',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 cebollas grandes',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 dientes de ajo',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 tomate maduro',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Pan frito o una rebanada de pan duro (para ligar, opcional)',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Poner los pimientos choriceros en remojo con agua caliente durante 30 minutos, hasta que estén blandos.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Rehogar la cebolla y el ajo picados muy finos en aceite de oliva a fuego lento durante 30-40 minutos, hasta que estén muy tiernos y dulces.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el tomate rallado y cocinar 10 minutos más.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Raspar la pulpa de los pimientos choriceros ya hidratados e incorporarla al sofrito.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Triturar toda la salsa hasta obtener una textura fina y homogénea; ajustar de sal.',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el bacalao a la salsa, con la piel hacia arriba, y cocinar a fuego suave 8-10 minutos, sin que hierva fuerte, hasta que esté en su punto.',5);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Marmitako de bonito','Guiso marinero nacido a bordo de los barcos atuneros: bonito, patata cascada y pimientos, en un caldo con el color del pimiento choricero.','1 h',60,'Media',4,'Vasca','principal','Nunca hiervas el bonito directamente en el guiso: se endurece. Añádelo siempre fuera del fuego y déjalo terminar de hacerse con el calor residual.','https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Marmitako_de_at%C3%BAn_%28Espa%C3%B1a%29.jpg/960px-Marmitako_de_at%C3%BAn_%28Espa%C3%B1a%29.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'600 g de bonito del norte fresco, en tacos',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'800 g de patatas',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 pimiento verde',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 pimiento rojo',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 dientes de ajo',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 pimientos choriceros (o 1 cucharada de pulpa de choricero)',6);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 tomate maduro',7);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 ml de caldo de pescado o fumet',8);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva, sal, laurel',9);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hidratar los pimientos choriceros en agua caliente y extraer su pulpa.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sofreír cebolla, ajo y pimientos picados en aceite de oliva hasta que estén tiernos.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el tomate rallado y la pulpa de choricero, cocinar unos minutos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cascar las patatas (cortar y romper al final del corte para que suelten almidón) e incorporarlas al sofrito. Rehogar 2-3 minutos.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cubrir con el caldo de pescado caliente y una hoja de laurel; cocinar a fuego medio 20-25 minutos hasta que la patata esté tierna.',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Retirar del fuego, añadir el bonito en tacos y dejar reposar tapado 3-4 minutos: el propio calor del guiso lo cocina sin que quede seco.',5);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Txangurro a la donostiarra','Carne de centollo o buey de mar guisada con verduras, un chorrito de brandy y gratinada al horno, servida en su propio caparazón.','1 h 15 min',75,'Media',4,'Vasca','principal','Desmigar bien la carne y retirar cualquier resto de caparazón es lo más laborioso pero también lo más importante del plato: hazlo con calma y buena luz.','https://live.staticflickr.com/2691/4449695487_6d08e303bd_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 centollos o buey de mar cocidos (aprox. 1,2 kg)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla picada',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1/2 puerro picado',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'50 ml de aceite de oliva',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'50 ml de tomate triturado',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 chorrito de brandy',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Perejil picado',6);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'20 g de mantequilla',7);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Pan rallado',8);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Separar con cuidado la carne del centollo del caparazón, desechando branquias, y desmigar bien. Reservar el caparazón limpio.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pochar la cebolla y el puerro en aceite de oliva a fuego suave hasta que estén muy tiernos.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el tomate triturado y cocinar unos minutos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar el brandy, dejar reducir, y añadir la carne del centollo. Cocinar 3-4 minutos removiendo con suavidad.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Rellenar los caparazones limpios con la mezcla, espolvorear con pan rallado y unos copos de mantequilla.',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Gratinar en el horno a 200 °C durante 8-10 minutos, hasta dorar la superficie.',5);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Kokotxas de bacalao al pil-pil','Las cocochas, la parte gelatinosa de la garganta del bacalao, cocinadas igual que el pil-pil clásico: una de las texturas más apreciadas de la cocina vasca.','30 min',30,'Alta',4,'Vasca','principal','Las kokotxas son muy delicadas: cocínalas siempre a fuego bajísimo y con movimientos suaves, nunca removiendo con una cuchara, o se deshacen.','https://commons.wikimedia.org/wiki/Special:FilePath/CocotxasPilPil.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'600 g de kokotxas de bacalao desaladas',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 ml de aceite de oliva virgen extra',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'3 dientes de ajo laminados',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 guindilla seca',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Perejil picado',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dorar los ajos laminados con la guindilla en el aceite a fuego suave; retirar y reservar.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Templar el aceite y añadir las kokotxas con la piel hacia abajo.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocinar a fuego muy bajo, moviendo la cazuela en vaivén constante (nunca con cuchara), durante 8-10 minutos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'La gelatina que sueltan las kokotxas irá ligando el aceite en una salsa cremosa; si hace falta, ayudar con movimientos circulares de la cazuela.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir de inmediato con los ajos, la guindilla y perejil picado por encima.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Txipirones en su tinta','Chipirones pequeños guisados en una salsa oscura de su propia tinta, cebolla y pimiento, tradicionalmente acompañados de arroz blanco.','1 h',60,'Media',4,'Vasca','principal','No cuezas los chipirones demasiado tiempo a fuego fuerte: quedan gomosos. Una cocción lenta y suave los deja tiernos de verdad.','https://commons.wikimedia.org/wiki/Special:FilePath/Zaragoza%20-%20Antiguo%20Bar%20La%20Jota%20-%20Calamares%20en%20su%20tinta.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 kg de chipirones pequeños limpios, con sus bolsas de tinta reservadas',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 cebollas picadas',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 pimiento verde picado',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 dientes de ajo',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 tomate maduro rallado',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'100 ml de vino blanco',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva, sal',6);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Arroz blanco para acompañar',7);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Limpiar los chipirones separando cuerpo, aletas y tentáculos; reservar las bolsas de tinta en un vaso con un poco de agua o vino.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pochar cebolla, pimiento y ajo en aceite de oliva a fuego lento hasta que estén muy tiernos.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el tomate rallado y cocinar unos minutos más.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar los chipirones troceados y el vino blanco, dejar reducir el alcohol.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Triturar la tinta disuelta y añadirla a la cazuela; cocinar a fuego suave 20-25 minutos hasta que los chipirones estén tiernos y la salsa espese.',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir con arroz blanco como guarnición.',5);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Angulas a la bilbaína','Angulas salteadas al momento con ajo y guindilla en cazuela de barro, un manjar tradicional de invierno en la ría del Nervión.','5 min',5,'Media',4,'Vasca','principal','El punto justo se pierde en segundos: ten todos los ingredientes preparados de antemano porque este plato no espera.','https://commons.wikimedia.org/wiki/Special:FilePath/Angulas%20al%20ajillo%2C%20Bilbao%20%2832941326932%29.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'400 g de angulas (o gulas como alternativa habitual hoy en día)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 dientes de ajo laminados',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 guindillas secas',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Calentar el aceite en una cazuela individual de barro con los ajos laminados y la guindilla, hasta que el ajo empiece a dorarse.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir las angulas y saltear apenas unos segundos, removiendo con dos tenedores de madera para que no se peguen.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Retirar del fuego en cuanto pierdan el color transparente (unos 30-40 segundos): se cocinan casi al instante.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir de inmediato en la misma cazuela, muy caliente.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Bonito con tomate','Lomos de bonito del norte guisados suavemente en una salsa de tomate casera, receta veraniega de cuando llega la costera del bonito.','45 min',45,'Fácil',4,'Vasca','principal','Marca el bonito muy poco antes de meterlo en la salsa: solo tiene que sellarse por fuera, el resto de la cocción la termina el tomate.','https://live.staticflickr.com/3192/2671809615_f139c1ee38_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 rodajas de bonito del norte',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 kg de tomate maduro',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 pimiento verde',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 dientes de ajo',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva, sal, azúcar (una pizca)',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Harina para enharinar el bonito',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pochar la cebolla, el pimiento y el ajo picados en aceite de oliva hasta que estén tiernos.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el tomate rallado o triturado y cocinar a fuego suave 25-30 minutos, hasta que la salsa espese. Corregir de sal y una pizca de azúcar si el tomate está ácido.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Salpimentar el bonito, enharinarlo ligeramente y marcarlo en una sartén con un poco de aceite, 1 minuto por cada lado, sin cocinarlo del todo.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Introducir el bonito en la salsa de tomate y terminar de cocinar 3-4 minutos a fuego suave.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir caliente, con la salsa por encima.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Sardinas a la parrilla','Sardinas frescas asadas a la brasa, plato sencillo y muy popular en las fiestas de verano de los pueblos costeros vascos.','15 min',15,'Fácil',4,'Vasca','principal','No las muevas demasiado en la parrilla: dales tiempo para que la piel se dore y se despeguen solas antes de darles la vuelta.','https://commons.wikimedia.org/wiki/Special:FilePath/Asadas%20al%20carb%C3%B3n.JPG','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'16 sardinas frescas, limpias',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal gruesa',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Limón',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Salar las sardinas generosamente por ambos lados con sal gruesa.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Asar en parrilla de carbón bien caliente, unos 2-3 minutos por cada lado, hasta que la piel esté dorada y crujiente.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Retirar con cuidado para que no se rompan.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir de inmediato con un chorrito de aceite de oliva virgen extra y unos gajos de limón.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Cogote de merluza a la donostiarra','El cogote, la parte más gelatinosa y sabrosa de la merluza, a la plancha con un refrito de ajo, guindilla y vinagre que hace \'chas\' al servirlo.','25 min',25,'Media',4,'Vasca','principal','El refrito debe llegar muy caliente a la mesa, verterlo sobre el pescado en el momento: ese chisporroteo final es parte de la experiencia del plato.','https://commons.wikimedia.org/wiki/Special:FilePath/Rodaja%20de%20merluza%20a%20la%20plancha%20y%20salsa%20de%20picada%20valenciana.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cogote de merluza grande (o 4 raciones)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 dientes de ajo laminados',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 guindilla seca',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'100 ml de aceite de oliva virgen extra',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharada de vinagre de sidra',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Salar el cogote y cocinarlo en una plancha o cazuela con un poco de aceite, a fuego medio, con la piel hacia abajo primero, hasta que esté hecho por dentro (unos 12-15 minutos según grosor).',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Aparte, calentar el aceite de oliva en una sartén pequeña y dorar los ajos laminados junto con la guindilla.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Retirar la sartén del fuego, añadir el vinagre con cuidado (salpica) y remover.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Verter este refrito bien caliente sobre el cogote justo antes de servir.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Changurro relleno al horno','Variante más especiada del txangurro clásico, con un toque de brandy y mostaza, gratinado hasta quedar dorado.','1 h 20 min',80,'Media',4,'Vasca','principal','La mostaza es opcional pero le da un contrapunto interesante a la dulzura del marisco: añádela poco a poco y prueba antes de rellenar.','https://commons.wikimedia.org/wiki/Special:FilePath/O_Nobre%20%2842982055121%29.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 centollos cocidos',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 zanahoria pequeña',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 cucharadas de tomate frito',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharadita de mostaza de Dijon',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Brandy',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Pan rallado y mantequilla para gratinar',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Extraer y desmigar la carne del centollo, reservando los caparazones.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Picar muy fino la cebolla y la zanahoria y pocharlas a fuego lento en un poco de aceite hasta que estén tiernas.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el tomate frito, la mostaza y un chorrito de brandy; cocinar 2 minutos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar la carne de centollo, mezclar bien y rectificar de sal.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Rellenar los caparazones, cubrir con pan rallado y unos trocitos de mantequilla.',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Gratinar en el horno a 200 °C hasta que la superficie esté dorada, unos 8 minutos.',5);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Gambas a la plancha con ajo','Gambas frescas cocinadas enteras a la plancha con sal gruesa y un refrito de ajo, clásico rápido de cualquier sidrería o asador vasco.','10 min',10,'Fácil',4,'Vasca','principal','No las cocines de más: en cuanto cambien de color y se curven ligeramente, están listas. El exceso de calor las deja gomosas.','https://live.staticflickr.com/3624/3469396193_e3640f7372_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'600 g de gambas frescas enteras',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal gruesa',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'3 dientes de ajo laminados',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Perejil picado',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Calentar bien la plancha y añadir un chorrito de aceite de oliva.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Colocar las gambas y espolvorear con sal gruesa. Cocinar 1-2 minutos por lado, sin moverlas demasiado, hasta que estén rosadas.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Aparte, calentar un poco de aceite con el ajo laminado hasta dorarlo ligeramente.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Verter el ajo y su aceite sobre las gambas recién hechas y espolvorear con perejil picado.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Txuletón a la brasa','El chuletón de vaca vieja asado sobre brasas de carbón vegetal, con la sal gruesa como único condimento: el plato insignia de los asadores vascos.','25 min',25,'Media',2,'Vasca','principal','Sala siempre después de asar, nunca antes: la sal extrae los jugos de la carne y reseca la superficie si se aplica con antelación.','https://commons.wikimedia.org/wiki/Special:FilePath/Chuleton_a_la_piedra.JPG','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 chuletón de vaca de al menos 1 kg y 4-5 cm de grosor',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal gruesa en escamas',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra (opcional)',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sacar la carne de la nevera al menos 1 hora antes para que esté a temperatura ambiente.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Preparar brasas de carbón de encina bien calientes, sin llama.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Asar el chuletón directamente sobre las brasas, 4-5 minutos por cada lado para un punto poco hecho, sellando bien la superficie.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Colocarlo de canto apoyado sobre el hueso unos minutos para que se termine de hacer sin resecarse.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Salar generosamente con sal gruesa justo después de asar, nunca antes.',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar reposar 3-4 minutos antes de cortar en lonchas gruesas.',5);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Txistorra a la sidra','El embutido fresco de cerdo típico vasco, cocinado a fuego lento con un chorro de sidra natural que aporta un punto ácido.','20 min',20,'Fácil',4,'Vasca','principal','Si tienes ocasión, prueba a flambear la txistorra con un chorrito de aguardiente antes de añadir la sidra: es una variante tradicional en fiestas y romerías.','https://upload.wikimedia.org/wikipedia/commons/a/a8/Chistorra.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'600 g de txistorra',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 ml de sidra natural',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharada de aceite de oliva',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pinchar ligeramente la txistorra con un tenedor para que no reviente al cocinarla.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dorarla en una sartén con un poco de aceite a fuego medio, dándole vueltas, durante 5-6 minutos.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir la sidra y dejar reducir a fuego medio-alto hasta que se forme una salsa ligera que envuelva la txistorra, unos 8-10 minutos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir bien caliente, cortada en trozos, idealmente con pan o como pintxo.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Alubias de Tolosa','Alubias negras pequeñas, con Denominación de Origen de Tolosa, cocinadas a fuego lento con su sacramento tradicional: berza, chorizo y morcilla.','2 h 30 min',150,'Media',6,'Vasca','principal','\'Asustar\' las alubias (añadir agua fría cuando hierven con fuerza) es el secreto para que queden enteras y con esa piel fina característica, sin que se rompan.','https://commons.wikimedia.org/wiki/Special:FilePath/Tolosako%20babarrunak.jpeg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 g de alubias negras de Tolosa',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla entera',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cabeza de ajo entera',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 hoja de laurel',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 chorizos frescos',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 morcillas',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 g de berza o repollo',6);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva, sal',7);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Poner las alubias en remojo la noche anterior en agua fría.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Al día siguiente, escurrir y cubrir con agua fría en una cazuela grande junto con la cebolla entera y la cabeza de ajo.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocer a fuego lento, sin sal, \'asustando\' con un chorro de agua fría cada vez que rompan a hervir con fuerza (2-3 veces), para que la piel no se abra.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cuando lleven cociendo aproximadamente 1 hora y media, añadir el laurel y un chorrito de aceite de oliva.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocer aparte la berza en agua con sal hasta que esté tierna, y el chorizo y la morcilla en agua aparte para desgrasarlos.',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir la berza escurrida, el chorizo y la morcilla a la cazuela de alubias y cocinar 20-30 minutos más a fuego muy suave hasta que todo esté meloso.',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Salar al final de la cocción, nunca al principio.',6);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Porrusalda','Sopa reconfortante de puerro y patata, de origen muy humilde, que da nombre en euskera a este binomio (\'porru\' puerro + \'salda\' caldo).','40 min',40,'Fácil',4,'Vasca','principal','Cascar las patatas en vez de cortarlas limpiamente hace que suelten almidón y el caldo quede más espeso de forma natural, sin necesidad de triturar nada.','https://upload.wikimedia.org/wikipedia/commons/1/19/Porrusalda.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 puerros grandes',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 patatas medianas',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 zanahoria',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla pequeña',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Bacalao desalado en trozos (opcional)',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Limpiar bien los puerros y cortarlos en rodajas, junto con la zanahoria y la cebolla.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pochar ligeramente estas verduras en un poco de aceite de oliva durante 5 minutos.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir las patatas cascadas (cortadas rompiendo el trozo final para que suelten almidón) y cubrir con agua.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocer a fuego medio 25-30 minutos hasta que las verduras estén muy tiernas.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Si se desea, añadir el bacalao en los últimos 5 minutos de cocción y dejar reposar tapado.',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Rectificar de sal y servir bien caliente.',5);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Piperrada vasca','Fritada de pimientos verdes y rojos, cebolla y tomate cocinados a fuego lento, base de muchos platos vascos y también protagonista por sí sola.','45 min',45,'Fácil',4,'Vasca','principal','La piperrada gana con la cocción lenta y larga: cuanto más tiempo a fuego bajo, más se concentran los sabores y menos ácida queda.','https://commons.wikimedia.org/wiki/Special:FilePath/Piperrada1.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 pimientos verdes',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 pimientos rojos',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 cebollas',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 tomates maduros',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 dientes de ajo',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal, una pizca de azúcar',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cortar los pimientos y la cebolla en tiras finas, y picar el ajo.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Rehogar la cebolla y el ajo en aceite de oliva a fuego suave hasta que estén transparentes.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir los pimientos y cocinar a fuego lento, tapado, removiendo de vez en cuando, durante 20 minutos hasta que estén muy tiernos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar el tomate pelado y troceado, sazonar y cocinar 15-20 minutos más a fuego suave hasta que todo quede meloso y sin exceso de líquido.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir como guarnición o acompañado de huevos, bacalao o jamón.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Menestra de verduras de temporada','Combinado de verduras de huerta cocidas y salteadas por separado, unidas en una cazuela con un ligero refrito, típica de la primavera vasca.','1 h',60,'Media',4,'Vasca','principal','Cocer cada verdura por separado en vez de todas juntas evita que unas queden pasadas mientras otras aún están duras: es más trabajo, pero marca la diferencia.','https://live.staticflickr.com/5139/5456431519_fc88992e96_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 g de habitas tiernas',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 g de guisantes',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 manojo de espárragos trigueros',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 alcachofas',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 zanahorias',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'100 g de jamón serrano en taquitos',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 dientes de ajo',6);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva, sal, harina (opcional para la salsa)',7);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocer por separado, en agua con sal, cada verdura hasta que esté tierna (las alcachofas y zanahorias tardarán más que las habitas y guisantes); escurrir y reservar el caldo de cocción.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dorar el jamón y el ajo picado en una cazuela con un poco de aceite.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir todas las verduras cocidas y saltear suavemente 2-3 minutos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar un cazo del caldo de cocción de las verduras y dejar que ligue ligeramente a fuego suave 5 minutos.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Rectificar de sal y servir caliente.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pochas con almejas','Alubias blancas frescas (pochas) guisadas con almejas, un plato de mar y montaña muy apreciado a finales de verano cuando llega la pocha fresca.','1 h',60,'Media',4,'Vasca','principal','Descarta cualquier almeja que no se abra al cocinarla: es señal de que no estaba en buen estado.','https://commons.wikimedia.org/wiki/Special:FilePath/Pochas%20a%20la%20riojana.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'600 g de pochas frescas (o alubias blancas cocidas)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 g de almejas',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 dientes de ajo',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 pimiento verde',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'100 ml de vino blanco',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva, sal, perejil',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Poner las almejas en agua con sal durante 30 minutos para que suelten la arena; enjuagar bien.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocer las pochas frescas en agua sin sal, a fuego suave, hasta que estén tiernas (unos 30-40 minutos si son frescas).',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Aparte, pochar la cebolla, el ajo y el pimiento picados en aceite de oliva.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el vino blanco y dejar reducir; incorporar las almejas y tapar hasta que se abran.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir las pochas cocidas con un poco de su caldo a la cazuela de almejas y cocinar juntas 5-10 minutos a fuego suave para que se integren los sabores.',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Espolvorear con perejil picado y servir caliente.',5);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pastel vasco (Gâteau Basque)','Tarta de masa quebrada rellena de crema pastelera o confitura de cereza negra, originaria del País Vasco francés.','1 h 30 min',90,'Media',8,'Vasca','postre','Refrigera bien la masa antes de trabajarla: es muy mantecosa y a temperatura ambiente resulta difícil de manejar sin que se rompa.','https://upload.wikimedia.org/wikipedia/commons/6/6b/G%C3%A2teau_Basque_in_Gastroteka_Bimendi_2020-05_ac.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 g de harina',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de mantequilla a temperatura ambiente',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de azúcar',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 huevos + 1 yema para pintar',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharadita de levadura',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Ralladura de un limón',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 ml de leche',6);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 yemas',7);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'80 g de azúcar (para la crema)',8);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'40 g de maicena',9);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 vaina de vainilla',10);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Preparar la crema pastelera: calentar la leche con la vainilla. Batir las yemas con el azúcar y la maicena, añadir la leche caliente poco a poco y cocinar a fuego suave hasta que espese. Dejar enfriar cubierta con film a piel.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Para la masa, batir la mantequilla con el azúcar hasta blanquear, añadir los huevos uno a uno y la ralladura de limón.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar la harina y la levadura hasta formar una masa homogénea. Envolver en film y refrigerar 30 minutos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dividir la masa en dos, estirar cada mitad y forrar un molde con la primera, rellenar con la crema pastelera fría y cubrir con la segunda lámina, sellando bien los bordes.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pintar con la yema batida y marcar la superficie con un tenedor formando el clásico dibujo de cuadrícula o la cruz vasca.',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hornear a 180 °C durante 35-40 minutos hasta que esté bien dorado.',5);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Tarta de queso donostiarra','La famosa tarta de queso \'quemada\', sin base ni corteza, creada en el bar La Viña de San Sebastián: exterior oscuro y caramelizado, interior cremoso.','1 h + reposo',60,'Fácil',8,'Vasca','postre','No te asustes si la superficie queda muy oscura, casi quemada: es la seña de identidad de esta tarta. El centro debe quedar cremoso, casi líquido en caliente, y asentarse al enfriar.','https://commons.wikimedia.org/wiki/Special:FilePath/Basque-cheesecake.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 kg de queso crema',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'400 g de azúcar',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'6 huevos',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 ml de nata para montar (35% M.G.)',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharada de harina',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Una pizca de sal',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Precalentar el horno a 220-230 °C y forrar un molde desmontable con papel de horno, dejando que sobresalga bastante por los bordes.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Batir el queso crema con el azúcar hasta que quede liso.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir los huevos de uno en uno, integrando bien cada uno antes de agregar el siguiente.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar la nata, la harina tamizada y la sal, mezclando hasta obtener una masa homogénea y sin grumos.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Verter en el molde y hornear entre 45 y 55 minutos, hasta que la superficie esté muy oscura y el centro tiemble ligeramente al mover el molde.',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar enfriar por completo a temperatura ambiente y refrigerar varias horas antes de desmoldar.',5);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Goxua','Postre de Vitoria-Gasteiz servido en cazuelita individual, con capas de nata montada, bizcocho y crema catalana caramelizada por encima.','40 min',40,'Media',4,'Vasca','postre','Sirve el goxua recién caramelizado: el contraste entre la costra crujiente aún caliente y la crema fría de debajo es lo que hace especial a este postre.','https://upload.wikimedia.org/wikipedia/commons/8/8e/Goxua.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 trozos de bizcocho tipo plancha',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 ml de almíbar o vino dulce (para calar el bizcocho)',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 ml de nata para montar',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'30 g de azúcar glas',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 ml de leche',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 yemas',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'80 g de azúcar',6);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'30 g de maicena',7);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Azúcar para caramelizar',8);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Preparar una crema pastelera espesa: calentar la leche, batir las yemas con el azúcar y la maicena, mezclar con la leche caliente y cocer a fuego suave hasta que espese. Enfriar.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Montar la nata con el azúcar glas hasta que esté firme.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Calar los trozos de bizcocho en el almíbar y colocarlos en el fondo de cada cazuelita individual.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cubrir con una capa de nata montada y encima una capa de crema pastelera fría.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Espolvorear con azúcar por encima y caramelizar con soplete de cocina o bajo el grill del horno hasta dorar.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Intxaursaltsa','Crema de nueces con leche y canela, postre navideño tradicional que se toma en Nochebuena en muchos hogares vascos.','30 min',30,'Fácil',4,'Vasca','postre','Remueve con frecuencia mientras espesa: al llevar frutos secos, se pega con facilidad en el fondo de la cazuela y puede quemarse.','https://upload.wikimedia.org/wikipedia/commons/0/0f/Cuisine_of_the_Basque_Country-Intxaursaltsa_001.JPG','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 g de nueces peladas',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 litro de leche entera',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de azúcar',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 rama de canela',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Canela molida para decorar',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Triturar las nueces hasta obtener una pasta fina, o machacarlas en un mortero para una textura más rústica.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Calentar la leche con la rama de canela y el azúcar sin dejar que hierva con fuerza.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir las nueces trituradas y cocinar a fuego muy suave, removiendo con frecuencia, durante 15-20 minutos hasta que espese ligeramente.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Retirar la rama de canela, repartir en cuencos individuales y dejar enfriar.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Espolvorear con canela molida antes de servir.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Mamia (cuajada de oveja)','Postre tradicional de leche de oveja cuajada, servido con miel o azúcar, herencia directa de la trashumancia y los pastores vascos.','20 min + reposo',20,'Fácil',4,'Vasca','postre','No muevas ni remuevas los cuencos mientras cuaja: cualquier movimiento puede romper la cuajada y que no llegue a tomar cuerpo.','https://commons.wikimedia.org/wiki/Special:FilePath/Cuajada_cropped_-_juantigues.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 litro de leche de oveja fresca',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 pastilla de cuajo (o unas gotas de cuajo líquido)',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Miel para acompañar',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Calentar la leche de oveja hasta que esté tibia (unos 37 °C), sin que llegue a hervir.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Disolver el cuajo según las indicaciones del fabricante y mezclarlo con la leche templada.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Repartir en cuencos individuales de barro y dejar reposar sin mover durante 30-40 minutos hasta que cuaje por completo.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Refrigerar antes de servir.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Acompañar con un buen chorro de miel al gusto.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Vasca','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Samosas de patata y guisantes','Empanadillas triangulares de masa crujiente rellenas de patata especiada y guisantes, el snack callejero más extendido de India.','1 h',60,'Media',4,'India','entrante','Fríe a fuego medio, nunca alto: así el interior se calienta bien sin que la masa se queme por fuera antes de tiempo.','https://upload.wikimedia.org/wikipedia/commons/c/c4/Samosas%2C_snack_food_at_Wikipedia%27s_16th_Birthday_celebration_in_Chittagong_%2801%29.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'250 g de harina',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 cucharadas de aceite o ghee',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Agua, sal',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'3 patatas cocidas y troceadas',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'100 g de guisantes',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla picada',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Jengibre rallado',6);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharadita de comino',7);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharadita de cilantro molido',8);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Garam masala, chile verde picado',9);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Cilantro fresco',10);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite para freír',11);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Amasar la harina con el aceite, sal y agua hasta lograr una masa firme; dejar reposar tapada 20 minutos.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sofreír la cebolla y el jengibre en aceite, añadir el comino y dejar que chisporrotee.',1);
