INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Biryani de pollo','Arroz basmati cocido en capas con pollo especiado, azafrán y hierbas frescas; plato festivo que se sirve en ocasiones especiales en toda India.','1 h 30 min',90,'Alta',6,'India','principal','Sella bien la olla antes de la cocción final \'dum\' para que el vapor no escape: así el arroz termina de hacerse con su propio calor sin perder aroma.','https://upload.wikimedia.org/wikipedia/commons/5/5a/%22Hyderabadi_Dum_Biryani%22.jpg','base');
