INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Gulab jamun','Bolitas de leche en polvo fritas y bañadas en un almíbar aromatizado con cardamomo y agua de rosas, el postre indio más extendido en celebraciones.','1 h',60,'Media',6,'India','postre','Fríe a fuego medio-bajo y sin prisa: si el aceite está demasiado caliente, se doran por fuera antes de cocinarse por dentro y quedan crudas en el centro.','https://upload.wikimedia.org/wikipedia/commons/5/56/Gulab_Jamun.jpg','base');
