INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Moussaka','Pastel de capas de berenjena frita, carne picada especiada con canela y bechamel gratinada.','1 h 30 min',90,'Media',6,'Griega','principal','Deja reposar la moussaka al menos 15 minutos fuera del horno antes de cortarla: así las capas no se desmoronan.','https://upload.wikimedia.org/wikipedia/commons/a/a8/MussakasMeMelitsanesKePatates01.JPG','base');
