INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pollo Kung Pao','Pollo salteado con cacahuetes, chiles secos y una salsa agridulce y ligeramente picante, plato icónico de la cocina de Sichuan.','30 min',30,'Media',4,'China','principal','Saltea siempre a fuego muy fuerte y en movimiento constante: es lo que da al plato su textura y sabor característicos del wok.','https://upload.wikimedia.org/wikipedia/commons/c/c2/Kung-pao-shanghai.jpg','base');
