INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pato laqueado (estilo Pekín)','Pato asado hasta que la piel queda crujiente y brillante, servido en finas tortitas con pepino, cebolleta y salsa hoisin.','3 h',180,'Alta',4,'China','principal','Secar muy bien la piel del pato antes de asarlo es el paso más importante: la humedad es el principal enemigo de una piel crujiente.','https://upload.wikimedia.org/wikipedia/commons/8/81/Peking_Duck%2C_2014_%2802%29.jpg','base');
