INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Berenjena a la Szechuan','Berenjena frita en una salsa agridulce y ligeramente picante con ajo, jengibre y cebolleta, plato vegetariano muy popular de Sichuan.','30 min',30,'Fácil',4,'China','principal','Seca bien las berenjenas después de salarlas: si conservan mucha agua, absorben demasiado aceite al freírlas.','https://live.staticflickr.com/3216/2965910624_20e91408c8_b.jpg','base');
