INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Huevo con tomate','Huevo revuelto suave con tomate salteado, plato casero muy sencillo que se prepara a diario en los hogares chinos.','15 min',15,'Fácil',4,'China','principal','No cuajes el huevo del todo la primera vez: debe quedar jugoso, porque se termina de cocinar al mezclarlo con el tomate.','https://upload.wikimedia.org/wikipedia/commons/a/a4/Huevosalplato.jpg','base');
