INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Carbonara','Espaguetis con una crema de huevo, queso pecorino y guanciale crujiente, sin nata, tal y como se hace en Roma.','20 min',20,'Media',4,'Italiana','principal','Mezcla el huevo con la pasta siempre fuera del fuego directo: el calor residual basta para cuajarlo suavemente sin que se convierta en huevo revuelto.','https://upload.wikimedia.org/wikipedia/commons/0/05/Classic-spaghetti-carbonara.jpg','base');
