INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Risotto alla milanese','Risotto cremoso teñido de amarillo con azafrán, especialidad de Milán que suele acompañar al ossobuco.','35 min',35,'Media',4,'Italiana','principal','La \'mantecatura\' final —remover con fuerza fuera del fuego al añadir mantequilla y queso— es lo que le da al risotto su textura cremosa característica.','https://upload.wikimedia.org/wikipedia/commons/f/fe/Risotto_saffron_and_pistachio_nuts_%2832645475042%29.jpg','base');
