INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Ossobuco','Jarrete de ternera con hueso, cocinado lentamente en vino blanco y verduras, tradicionalmente acompañado de risotto milanés.','2 h',120,'Media',4,'Italiana','principal','No retires el tuétano del hueso: es una de las partes más apreciadas del plato y se puede untar directamente en el pan.','https://upload.wikimedia.org/wikipedia/commons/2/24/Osobuco_-_2010-10-20.jpg','base');
