INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Saltimbocca alla romana','Filetes finos de ternera con jamón crudo y salvia, salteados y terminados con una salsa de mantequilla y vino blanco.','25 min',25,'Fácil',4,'Italiana','principal','Cocina los filetes muy poco tiempo: son finos y se secan enseguida si se dejan demasiado en la sartén.','https://live.staticflickr.com/3362/3336228234_153073b004.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'8 filetes finos de ternera',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'8 lonchas de jamón crudo (prosciutto)',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'8 hojas de salvia fresca',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Harina, mantequilla',3);
