INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Parmigiana di melanzane','Capas de berenjena frita, salsa de tomate y queso, gratinadas al horno, especialidad del sur de Italia.','1 h 15 min',75,'Media',6,'Italiana','principal','Deja reposar la parmigiana unos minutos fuera del horno antes de cortarla: se corta en porciones mucho más limpias.','https://upload.wikimedia.org/wikipedia/commons/7/72/Parmigiana_di_melanzane.jpg','base');
