INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hornear a 180 °C 30-35 minutos hasta que esté bien gratinado y burbujeante.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Italiana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pizza margherita','La pizza napolitana original, con solo tomate, mozzarella y albahaca, horneada a temperatura muy alta.','2 h (con fermentado)',120,'Media',4,'Italiana','principal','Hornea siempre a la temperatura más alta que permita tu horno: el calor intenso y rápido es lo que da a la masa napolitana su borde esponjoso.','https://upload.wikimedia.org/wikipedia/commons/a/a3/Eq_it-na_pizza-margherita_sep2005_sml.jpg','base');
