INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Vitello tonnato','Finas lonchas de ternera fría cubiertas con una salsa cremosa de atún y alcaparras, entrante clásico del Piamonte.','40 min + enfriado',40,'Media',4,'Italiana','principal','Cuece la carne el día anterior y déjala enfriar en la nevera: se corta en lonchas mucho más finas y limpias en frío.','https://upload.wikimedia.org/wikipedia/commons/9/99/Vitello_tonnato_%287169906567%29.jpg','base');
