INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Italiana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Tiramisù','Capas de bizcochos de soletilla calados en café, crema de mascarpone y cacao en polvo, sin hornear.','30 min + reposo',30,'Fácil',6,'Italiana','postre','Moja los bizcochos muy rápido, casi un segundo por cada lado: si se empapan demasiado, el tiramisù queda aguado.','https://upload.wikimedia.org/wikipedia/commons/b/b5/Home-made_tiramisu%2C_november_2008.jpg','base');
