INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Panna cotta','Postre de nata cocida cuajada con gelatina, suave y ligeramente dulce, servido con un coulis de frutos rojos.','20 min + reposo',20,'Fácil',4,'Italiana','postre','No dejes que la nata hierva con fuerza: si se calienta demasiado, la textura final queda menos sedosa.','https://upload.wikimedia.org/wikipedia/commons/0/01/Panna_cotta_with_chocolate_mousse.jpg','base');
