INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Guacamole','Puré de aguacate machacado con lima, cilantro, cebolla y chile, la salsa mexicana más conocida en el mundo.','15 min',15,'Fácil',4,'Mexicana','entrante','El zumo de lima no solo da sabor: su acidez retrasa la oxidación del aguacate y mantiene el guacamole verde más tiempo.','https://upload.wikimedia.org/wikipedia/commons/7/7a/Lindo_Mexico_II_-_November_3_2023_-_Sarah_Stierch_02.jpg','base');
