INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Elote a la mexicana','Mazorca de maíz asada, untada con mayonesa, queso rallado, chile en polvo y lima, snack callejero muy popular.','20 min',20,'Fácil',4,'Mexicana','entrante','Asa el maíz directamente sobre la llama o brasas si es posible: el toque ligeramente tostado es parte esencial del sabor del elote.','https://upload.wikimedia.org/wikipedia/commons/f/f5/CookedCornOnTheCob.JPG','base');
