INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Tacos al pastor','Cerdo marinado en achiote y chiles, asado en trompo (o a la plancha) y servido en tortilla de maíz con piña y cilantro.','1 h + marinado',60,'Media',4,'Mexicana','principal','Deja marinar el cerdo toda la noche si es posible: los chiles y el achiote necesitan tiempo para penetrar bien en la carne.','https://upload.wikimedia.org/wikipedia/commons/d/d1/%28El_Flaco%29_Al_Pastor_Tacos.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'800 g de lomo de cerdo en filetes finos',0);
