INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Marinar el cerdo con esta pasta al menos 2 horas, mejor toda la noche.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Asar el cerdo en una plancha muy caliente hasta que esté bien dorado y hecho, y cortar en trozos pequeños.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Asar también unas rodajas de piña hasta que se caramelicen.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir en tortillas de maíz calientes con el cerdo, un trozo de piña asada, cebolla y cilantro picados.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mexicana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Enchiladas verdes','Tortillas rellenas de pollo desmenuzado, bañadas en una salsa verde de tomatillo y gratinadas con queso y crema.','45 min',45,'Media',4,'Mexicana','principal','Pasa las tortillas por la salsa caliente antes de rellenarlas: así se ablandan y no se rompen al enrollarlas.','https://live.staticflickr.com/3231/2740018526_ddda7f2e4a_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'12 tortillas de maíz',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'400 g de pechuga de pollo cocida y desmenuzada',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 g de tomatillos',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 chiles serranos',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 diente de ajo, cilantro fresco',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Queso fresco rallado, crema mexicana o nata agria',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hervir los tomatillos y los chiles hasta que estén tiernos, y triturar junto con el ajo y el cilantro hasta obtener una salsa verde.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Calentar la salsa en una sartén unos minutos.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pasar cada tortilla brevemente por la salsa caliente para ablandarla, rellenar con pollo desmenuzado y enrollar.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Colocar las enchiladas en una fuente, cubrir con más salsa verde, queso rallado y un poco de crema.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Gratinar unos minutos en el horno antes de servir.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mexicana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Chiles rellenos','Chiles poblanos asados, pelados y rellenos de queso, rebozados en huevo y fritos, bañados en salsa de tomate.','1 h',60,'Alta',4,'Mexicana','principal','Deja los chiles asados \'sudando\' dentro de un paño o bolsa cerrada unos minutos: así se despega la piel con mucha más facilidad.','https://upload.wikimedia.org/wikipedia/commons/5/53/Chile_Rellenos.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 chiles poblanos grandes',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 g de queso Oaxaca o similar',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Harina, huevos (separados)',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'400 g de tomate triturado',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Cebolla, ajo',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite para freír',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Asar los chiles directamente sobre la llama hasta que la piel se ampolle, envolver en un paño para sudar y pelar con cuidado.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hacer un corte lateral en cada chile y retirar las semillas, dejando el tallo intacto; rellenar con el queso.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Montar las claras a punto de nieve y añadir las yemas con suavidad para hacer el rebozado.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Enharinar los chiles rellenos, pasarlos por el huevo montado y freír en aceite caliente hasta dorar por todos lados.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Preparar una salsa sencilla sofriendo cebolla y ajo con el tomate triturado, y servir los chiles bañados en ella.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mexicana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Mole poblano','Salsa compleja de chiles secos, especias, frutos secos y chocolate, cocinada lentamente, tradicionalmente sobre pavo o pollo.','2 h',120,'Alta',6,'Mexicana','principal','Remueve el mole con frecuencia mientras cocina a fuego lento: al llevar frutos secos y chocolate, tiende a pegarse en el fondo de la olla.','https://upload.wikimedia.org/wikipedia/commons/e/e7/Mole_in_Puebla.JPG','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Piezas de pollo o pavo',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Chiles mulato, ancho y pasilla',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Almendras, cacahuetes, pasas',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Tomate, cebolla, ajo',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Canela, clavo, pimienta',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Chocolate mexicano o de mesa',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Tostar los chiles secos en una sartén sin aceite, hidratarlos en agua caliente y triturarlos con el tomate, la cebolla y el ajo.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Tostar por separado las almendras, los cacahuetes y las pasas, y triturarlos con las especias.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocinar el pollo o el pavo hasta que esté hecho, reservando el caldo.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sofreír la pasta de chile en una olla con un poco de aceite, añadir la pasta de frutos secos y especias, e incorporar el caldo de cocción del pollo poco a poco.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocinar a fuego muy lento removiendo con frecuencia durante al menos 40-50 minutos, y añadir el chocolate al final, removiendo hasta que se funda; servir sobre el pollo.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mexicana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pozole rojo','Sopa espesa de maíz cacahuazintle y cerdo en un caldo rojo de chiles secos, servida con lechuga, rábano y orégano.','2 h',120,'Media',6,'Mexicana','principal','Cuela bien la salsa de chile antes de añadirla al caldo: así el pozole queda con una textura fina, sin trozos de piel de chile.','https://live.staticflickr.com/47/394809762_6a0a29d893.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'800 g de maíz cacahuazintle cocido (pozole)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'800 g de carne de cerdo (aguja o costilla)',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Chiles guajillo y ancho',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Ajo, cebolla',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Lechuga, rábano, cebolla y orégano (para servir)',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocer la carne de cerdo en agua con ajo y cebolla hasta que esté muy tierna, reservando el caldo.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hidratar los chiles secos en agua caliente y triturarlos con un poco de ajo hasta obtener una salsa.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Colar la salsa de chile e incorporarla al caldo de cerdo.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el maíz cocido y la carne desmenuzada, y cocinar todo junto a fuego suave 30-40 minutos.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir muy caliente, acompañado de lechuga en juliana, rábano en rodajas, cebolla picada y orégano seco para que cada comensal se sirva a su gusto.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mexicana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Cochinita pibil','Cerdo marinado en achiote y zumo de naranja agria, cocinado muy lentamente envuelto en hoja de plátano hasta deshacerse.','3 h + marinado',180,'Media',6,'Mexicana','principal','Pasa las hojas de plátano brevemente por una llama o sartén caliente antes de envolver la carne: se vuelven flexibles y no se rompen.','https://upload.wikimedia.org/wikipedia/commons/8/84/Cochinita_pibil_2.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1,5 kg de paleta de cerdo',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'100 g de pasta de achiote',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Zumo de naranja agria (o naranja y lima mezcladas)',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Ajo, comino, orégano',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Hojas de plátano',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Cebolla morada encurtida (para servir)',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Disolver la pasta de achiote en el zumo de naranja agria junto con el ajo, el comino y el orégano.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Marinar el cerdo con esta mezcla al menos 4 horas, mejor toda la noche.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Envolver el cerdo marinado en hojas de plátano ligeramente pasadas por el fuego para ablandarlas.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocinar en el horno a baja temperatura, 150 °C, durante 3 horas, hasta que la carne se deshaga con facilidad.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Desmenuzar la carne y servirla en tacos con cebolla morada encurtida.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mexicana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Tamales de pollo','Masa de maíz rellena de pollo en salsa, envuelta en hoja de maíz y cocida al vapor, plato festivo en toda Mesoamérica.','1 h 30 min',90,'Alta',6,'Mexicana','principal','Bate bien la manteca antes de mezclarla con la masa: cuanto más aire incorpores en este paso, más ligeros quedarán los tamales.','https://live.staticflickr.com/7174/6789380415_ed55da2fc9_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 g de masa de maíz (masa harina)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'250 g de manteca de cerdo',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Caldo de pollo, sal, levadura en polvo',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'400 g de pollo cocido y desmenuzado',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Salsa roja o verde',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Hojas de maíz secas remojadas',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Remojar las hojas de maíz en agua caliente hasta que estén flexibles.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Batir la manteca hasta que esté esponjosa, añadir la masa, el caldo, la sal y la levadura poco a poco hasta lograr una masa suave y aireada.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Mezclar el pollo desmenuzado con la salsa roja o verde.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Extender una capa de masa sobre cada hoja de maíz, añadir una cucharada de relleno de pollo y doblar cerrando bien el tamal.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocer al vapor de pie, en posición vertical, durante 1 hora aproximadamente, hasta que la masa se despegue con facilidad de la hoja.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mexicana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Chilaquiles verdes','Totopos de maíz bañados en salsa verde, con crema, queso fresco y a menudo un huevo o pollo desmenuzado por encima.','30 min',30,'Fácil',4,'Mexicana','principal','Sirve los chilaquiles inmediatamente después de mezclar los totopos con la salsa caliente: si esperas demasiado, pierden el punto crujiente.','https://live.staticflickr.com/95/253919676_148488fa1c_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 g de totopos de maíz (o tortillas fritas troceadas)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 g de tomatillos',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 chiles serranos',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Ajo, cilantro',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Crema mexicana, queso fresco, cebolla',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Pollo desmenuzado o huevos fritos (opcional)',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hervir los tomatillos y los chiles hasta que estén tiernos, triturar con ajo y cilantro para obtener una salsa verde.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Calentar la salsa en una sartén amplia.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir los totopos y mezclar con cuidado para que se impregnen bien de salsa sin deshacerse del todo.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir de inmediato con crema, queso fresco desmenuzado, cebolla picada y, si se desea, pollo desmenuzado o un huevo frito por encima.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mexicana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Sopa de tortilla','Caldo de tomate y chile con tiras de tortilla frita, aguacate y queso, plato de cuchara muy popular en México.','40 min',40,'Fácil',4,'Mexicana','principal','Añade las tortillas fritas justo antes de servir, no dentro del caldo hirviendo: así conservan parte de su textura crujiente.','https://upload.wikimedia.org/wikipedia/commons/9/9a/Tortilla_Soup.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'6 tortillas de maíz en tiras',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 litro de caldo de pollo',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 tomates',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 chile ancho, 1 diente de ajo, 1/2 cebolla',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aguacate, queso fresco, crema, aceite para freír',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Freír las tiras de tortilla en aceite hasta que estén doradas y crujientes; escurrir.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Asar el tomate, el ajo y la cebolla, y triturarlos junto con el chile ancho hidratado.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sofreír esta salsa en una olla, añadir el caldo de pollo y cocinar 15-20 minutos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir el caldo caliente en boles con las tiras de tortilla, aguacate en dados, queso fresco y un poco de crema por encima.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mexicana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Carnitas','Cerdo cocinado lentamente en su propia grasa hasta quedar tierno por dentro y dorado por fuera, base de innumerables tacos.','3 h',180,'Media',6,'Mexicana','principal','No tengas prisa en la fase final de dorado: es el paso que da a las carnitas su contraste entre lo tierno de dentro y lo crujiente de fuera.','https://upload.wikimedia.org/wikipedia/commons/e/e6/Carnitas_in_Mexico.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1,5 kg de paleta de cerdo en trozos grandes',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Manteca de cerdo o aceite',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Naranja, ajo, hoja de laurel',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal, comino',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Tortillas de maíz para servir',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Colocar el cerdo en una olla amplia con manteca, el zumo y la piel de naranja, el ajo, el laurel, la sal y el comino.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cubrir apenas con agua y cocinar a fuego lento y constante durante 2 horas, hasta que la carne esté muy tierna.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Subir el fuego los últimos 20-30 minutos, sin tapar, dejando que el agua se evapore y la carne se dore en su propia grasa.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Desmenuzar la carne con dos tenedores, dejando algunos trozos crujientes.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir en tacos calientes con cebolla, cilantro y una salsa al gusto.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mexicana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Flan mexicano','Postre cremoso de huevo y leche condensada bañado en caramelo, versión mexicana del flan clásico.','1 h + refrigeración',60,'Media',6,'Mexicana','postre','Cocina siempre al baño maría: el calor directo del horno hace que el flan se llene de agujeros en vez de quedar liso y cremoso.','https://live.staticflickr.com/1261/4603207498_98229a1879_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de azúcar (para el caramelo)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 huevos',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 lata de leche condensada',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 lata de leche evaporada',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharadita de esencia de vainilla',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Derretir el azúcar en un molde a fuego medio hasta obtener un caramelo dorado, y repartirlo por el fondo del molde.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Batir los huevos con la leche condensada, la leche evaporada y la vainilla hasta integrar bien, sin batir en exceso para no generar demasiada espuma.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Verter la mezcla sobre el caramelo en el molde.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocinar al baño maría en el horno a 160 °C durante 50-60 minutos, hasta que esté cuajado pero aún tiemble ligeramente en el centro.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar enfriar por completo y refrigerar varias horas antes de desmoldar.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mexicana','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Churros con chocolate','Masa frita en forma de tira acanalada, rebozada en azúcar y canela, servida con chocolate caliente espeso para mojar.','40 min',40,'Media',4,'Mexicana','postre','La masa debe estar templada, ni caliente ni fría, al meterla en la manga: si está demasiado caliente puede deformarse al freír.','https://upload.wikimedia.org/wikipedia/commons/4/47/Chocolate_con_churros_de_lazo.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'250 ml de agua',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'50 g de mantequilla',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharadita de sal',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de harina',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite para freír',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Azúcar y canela molida (para rebozar)',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 g de chocolate negro, 300 ml de leche (para el chocolate caliente)',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hervir el agua con la mantequilla y la sal; retirar del fuego y añadir la harina de golpe, removiendo enérgicamente hasta formar una masa lisa que se despegue de las paredes.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar templar unos minutos e introducir la masa en una manga pastelera con boquilla en forma de estrella.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Freír tiras de masa directamente en aceite caliente, cortándolas con unas tijeras, hasta que estén doradas y crujientes.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Escurrir y rebozar en una mezcla de azúcar y canela mientras aún están calientes.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Calentar la leche con el chocolate troceado, removiendo hasta obtener un chocolate espeso, y servir junto a los churros.',4);
