INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Som tam (ensalada de papaya verde)','Ensalada picante y ácida de papaya verde rallada, tomate, judía larga y cacahuetes, machacada en mortero.','20 min',20,'Media',4,'Tailandesa','entrante','Machaca con movimientos suaves de golpeo, no de trituración: el objetivo es que los ingredientes suelten su jugo sin convertirse en puré.','https://upload.wikimedia.org/wikipedia/commons/1/1c/%E0%B8%95%E0%B8%B3%E0%B9%84%E0%B8%97%E0%B8%A2%E0%B9%84%E0%B8%82%E0%B9%88%E0%B9%80%E0%B8%84%E0%B9%87%E0%B8%A1_%E0%B8%AA%E0%B9%89%E0%B8%A1%E0%B8%95%E0%B8%B3_%E0%B8%95%E0%B8%B3%E0%B8%96%E0%B8%B2%E0%B8%94_Tumtaad_%E0%B8%81%E0%B8%A3%E0%B8%B0%E0%B8%9A%E0%B8%B5%E0%B9%88_01.jpg','base');
