INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pad thai','Fideos de arroz salteados con gambas, huevo, cacahuetes y tamarindo, el plato de fideos más internacional de Tailandia.','30 min',30,'Media',4,'Tailandesa','principal','No remojes los fideos hasta que estén blandos del todo: terminan de cocinarse en el wok y si ya están muy blandos se rompen al saltear.','https://upload.wikimedia.org/wikipedia/commons/3/39/Phat_Thai_kung_Chang_Khien_street_stall.jpg','base');
