INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Tod mun pla (pastelitos de pescado)','Pastelitos fritos de pasta de pescado con pasta de curry rojo y judía larga picada, crujientes por fuera y elásticos por dentro.','30 min',30,'Media',4,'Tailandesa','principal','Trabaja la pasta de pescado con energía, casi golpeándola contra el bol: ese amasado es lo que le da la textura elástica característica.','https://upload.wikimedia.org/wikipedia/commons/f/fc/Thanin_market_banana_flowers_and_leaves.jpg','base');
