INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Mango sticky rice','Arroz glutinoso cocido al vapor y bañado en leche de coco dulce, servido con láminas de mango fresco maduro.','1 h (con remojo)',60,'Fácil',4,'Tailandesa','postre','Remoja el arroz glutinoso el tiempo necesario: si no se hidrata lo suficiente, queda duro por dentro aunque parezca cocido por fuera.','https://live.staticflickr.com/4094/4887701660_9f5c750a21_b.jpg','base');
