INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Khanom krok (buñuelos de coco)','Pequeños buñuelos de coco cocinados en una sartén especial con moldes redondos, crujientes por fuera y cremosos por dentro.','40 min',40,'Media',4,'Tailandesa','postre','Cocina a fuego medio-bajo y con paciencia: el fuego fuerte quema la base antes de que el centro llegue a cuajar.','https://upload.wikimedia.org/wikipedia/commons/5/55/Khanom_Krok.jpg','base');
