INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Cordero tagine con ciruelas','Cordero guisado lentamente con ciruelas pasas, almendras y especias dulces, un clásico agridulce de la cocina marroquí.','2 h',120,'Media',4,'Marroquí','principal','Deja que la salsa reduzca sin tapa en los últimos minutos: es lo que concentra el dulzor de las ciruelas y la miel.','https://upload.wikimedia.org/wikipedia/commons/3/3a/Tajine-marocain-un-plat-varie-et-sain_%28cropped%29.jpg','base');
