INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Kefta tagine (albóndigas en salsa de tomate)','Albóndigas de carne especiada cocinadas en una salsa de tomate especiada, con huevos escalfados encima al final.','45 min',45,'Fácil',4,'Marroquí','principal','No remuevas las albóndigas con cuchara una vez en la salsa: mueve la cazuela con la mano para que no se deshagan.','https://live.staticflickr.com/3597/3697198543_7be1180b72_b.jpg','base');
