INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Cuscús con siete verduras','Sémola de trigo cocida al vapor, acompañada de un guiso de siete verduras y garbanzos, plato festivo del viernes en Marruecos.','1 h 30 min',90,'Media',6,'Marroquí','principal','Esponja la sémola con un tenedor varias veces durante el proceso: es lo que evita que quede apelmazada en bloques.','https://upload.wikimedia.org/wikipedia/commons/0/0c/Moroccan_cuscus%2C_from_Casablanca%2C_September_2018.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 g de sémola de cuscús',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Zanahoria, calabacín, nabo, calabaza, col, patata',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 g de garbanzos cocidos',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Cebolla, jengibre, cúrcuma, canela',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva, caldo o agua',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sofreír la cebolla con las especias en una olla ancha.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir las verduras más duras (zanahoria, nabo) y cubrir con agua o caldo, cocinar 20 minutos.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar el resto de verduras y los garbanzos, y seguir cocinando hasta que todas estén tiernas.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hidratar la sémola de cuscús con un poco de agua y aceite, y cocinarla al vapor sobre el guiso o siguiendo las instrucciones del paquete, esponjándola con un tenedor.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir la sémola con las verduras y el caldo del guiso por encima.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Marroquí','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Mechoui (cordero asado)','Cordero asado muy lentamente hasta que la carne se separa del hueso con solo tocarla, condimentado con especias sencillas.','3 h 30 min',210,'Media',6,'Marroquí','principal','La clave del mechoui es la temperatura baja y el tiempo largo: no tengas prisa, es lo que hace que la carne se separe del hueso sin necesidad de cuchillo.','https://upload.wikimedia.org/wikipedia/commons/9/96/Mechoui.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 pierna o paletilla de cordero grande',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Mantequilla, aceite de oliva',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Comino, sal, pimentón',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Ajo',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Frotar el cordero con una mezcla de mantequilla derretida, aceite, ajo machacado, comino, pimentón y sal.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Colocar en una bandeja de horno y cubrir con papel de aluminio.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Asar a temperatura baja, 150 °C, durante al menos 3 horas, regando de vez en cuando con sus propios jugos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Destapar los últimos 20-30 minutos para dorar bien la superficie.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir espolvoreado con más comino y sal, para que cada comensal moje la carne al gusto.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Marroquí','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Rfissa','Plato reconfortante de pollo y lentejas con especias, servido sobre trozos de pan plano o msemen deshilachado.','1 h 30 min',90,'Media',4,'Marroquí','principal','Deja reposar el pan en el caldo unos minutos antes de servir: necesita tiempo para absorberlo sin deshacerse del todo.','https://live.staticflickr.com/454/20110756839_c68705420d_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 pollo troceado',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de lentejas',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Jengibre, cúrcuma, ras el hanout',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Pan msemen o pan plano troceado',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Cilantro fresco',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dorar el pollo con la cebolla y las especias en una olla con un poco de aceite.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cubrir con agua y cocinar 30 minutos.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir las lentejas y seguir cocinando 30-40 minutos más hasta que estén tiernas y el caldo haya espesado.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Trocear el pan y colocarlo en el fondo de una fuente honda.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Verter el pollo, las lentejas y el caldo caliente sobre el pan, dejando que lo absorba antes de servir.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Marroquí','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Batbout (pan marroquí)','Pan plano cocido en sartén, sin horno, que se hincha formando una bolsa hueca ideal para rellenar.','1 h 30 min (con reposo)',90,'Media',4,'Marroquí','principal','Cocina a fuego medio, ni muy fuerte ni muy suave: el calor moderado es lo que permite que el pan se hinche formando la bolsa interior.','https://upload.wikimedia.org/wikipedia/commons/4/45/Pains_matlou_dans_une_boulangerie_de_la_rue_d%27Aligre%2C_%C3%A0_Paris.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 g de harina de trigo',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de sémola fina',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharadita de levadura seca',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Agua tibia, sal',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sémola extra para espolvorear',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Disolver la levadura en agua tibia y dejar activar 10 minutos.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Mezclar con la harina, la sémola y la sal, amasando hasta obtener una masa suave y elástica.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar fermentar tapada 1 hora hasta que doble su volumen.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dividir en bolas, aplanar en discos no muy finos y dejar reposar 15 minutos más.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocinar en una sartén o plancha seca a fuego medio, dándoles la vuelta varias veces, hasta que se hinchen y doren por ambos lados.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Marroquí','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Ensalada marroquí de tomate y pimiento asado','Ensalada cocida de tomate y pimiento asados, especiada con comino y pimentón, servida fría como acompañamiento.','40 min',40,'Fácil',4,'Marroquí','principal','Deja que la salsa de tomate reduzca bien antes de añadir el pimiento: si queda demasiado líquida, la ensalada pierde consistencia.','https://live.staticflickr.com/3515/3697196377_2f36655ee8_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 tomates maduros',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 pimientos rojos',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 dientes de ajo',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Comino, pimentón',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva, zumo de limón',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Cilantro o perejil fresco',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Asar los pimientos hasta que la piel se ampolle, pelarlos y cortarlos en tiras.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pelar los tomates escaldándolos en agua hirviendo y triturar la pulpa.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sofreír el ajo en aceite de oliva, añadir el tomate y las especias y cocinar 15-20 minutos hasta que espese.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar el pimiento asado en tiras y cocinar 5 minutos más.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar enfriar, aliñar con zumo de limón y servir con cilantro o perejil fresco.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Marroquí','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pastela de pollo','Empanada dulce y salada de pasta warqa rellena de pollo especiado, almendra y canela, espolvoreada con azúcar glas.','1 h 30 min',90,'Alta',6,'Marroquí','principal','No te asustes por la mezcla de dulce y salado: es la seña de identidad de la pastela, y el contraste es lo que la hace única.','https://upload.wikimedia.org/wikipedia/commons/e/ed/Bisteeya.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 pollo troceado',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla, jengibre, cúrcuma, canela',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'3 huevos',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de almendra frita y picada',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Azúcar, canela molida (para decorar)',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Láminas de pasta warqa o filo',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Mantequilla derretida',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocinar el pollo con la cebolla y las especias hasta que esté muy tierno; desmenuzarlo y reservar el caldo.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Reducir el caldo y ligarlo con los huevos batidos, removiendo a fuego suave hasta obtener una especie de revuelto cremoso.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Mezclar el pollo desmenuzado con este revuelto y dejar enfriar.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Forrar un molde con láminas de pasta warqa pintadas de mantequilla, rellenar con el pollo y la almendra picada, y cerrar con más láminas por encima.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hornear a 180 °C hasta dorar y espolvorear con azúcar glas y canela formando un dibujo en rombos antes de servir.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Marroquí','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Chebakia','Pasteles fritos en forma de flor, bañados en miel y espolvoreados con sésamo, típicos del Ramadán.','1 h 30 min',90,'Alta',8,'Marroquí','postre','Sumerge los pasteles en miel justo al salir del aceite, todavía calientes: así absorben mejor la miel y quedan brillantes.','https://upload.wikimedia.org/wikipedia/commons/4/44/Shebbaqu%C3%ADas.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 g de harina',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Canela, anís, sésamo tostado',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Levadura, mantequilla, vinagre',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Agua de azahar',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite para freír',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Miel para bañar',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Mezclar la harina con las especias, el sésamo tostado molido, la mantequilla y el vinagre.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Amasar añadiendo agua de azahar poco a poco hasta obtener una masa elástica; dejar reposar 30 minutos.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Estirar la masa fina y cortar en tiras, formando trenzas o flores dando forma con los dedos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Freír en aceite caliente hasta que estén doradas.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sumergir inmediatamente en miel templada y espolvorear con sésamo tostado.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Marroquí','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Cuernos de gacela (kaab el ghazal)','Pastelitos en forma de media luna rellenos de pasta de almendra aromatizada con agua de azahar y canela.','1 h',60,'Media',8,'Marroquí','postre','No hornees en exceso: estos pastelitos deben quedar pálidos y tiernos, no dorados y crujientes.','https://upload.wikimedia.org/wikipedia/commons/6/61/%D9%83%D8%B9%D8%A8_%D8%A7%D9%84%D8%BA%D8%B2%D8%A7%D9%84.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 g de almendra molida',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de azúcar glas',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Agua de azahar, canela',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'250 g de harina, mantequilla',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Huevo (para pintar)',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Mezclar la almendra molida con el azúcar glas, la canela y agua de azahar hasta formar una pasta moldeable.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Formar pequeños cilindros finos con la pasta de almendra.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Preparar una masa de harina y mantequilla, estirarla fina y envolver cada cilindro de almendra, dando forma de media luna.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pinchar ligeramente la superficie con un tenedor y pintar con huevo batido.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hornear a 180 °C 15-18 minutos hasta que estén dorados pero no oscuros.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Marroquí','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Té a la menta marroquí','Té verde con abundante menta fresca y azúcar, servido desde muy alto para formar espuma, símbolo de hospitalidad en Marruecos.','15 min',15,'Fácil',4,'Marroquí','postre','Desechar la primera agua de infusión del té es un paso tradicional que suaviza el amargor sin perder aroma.','https://upload.wikimedia.org/wikipedia/commons/4/41/Tunisian_Tea_with_pine_nuts.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 cucharadas de té verde gunpowder',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Un manojo grande de menta fresca',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Azúcar al gusto',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Agua',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Escaldar el té verde con un poco de agua caliente y desechar esa primera agua para suavizar el amargor.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir agua hirviendo de nuevo junto con la menta fresca y el azúcar.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar infusionar 5 minutos a fuego muy suave, sin que hierva con fuerza.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir vertiendo el té desde bastante altura sobre el vaso, para que se forme una ligera espuma en la superficie.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Marroquí','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Soupe à l\'oignon gratinée','Sopa de cebolla caramelizada muy lentamente, cubierta con pan tostado y queso gratinado, clásico de los bistrós parisinos.','1 h 30 min',90,'Media',4,'Francesa','entrante','No aceleres la caramelización de la cebolla: cuanto más lenta y larga sea esta fase, más profundo será el sabor final de la sopa.','https://upload.wikimedia.org/wikipedia/commons/5/5a/Soupe_%C3%A0_l%27oignon.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'6 cebollas grandes en juliana',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'50 g de mantequilla',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 litro de caldo de carne',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'100 ml de vino blanco',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Pan tostado (baguette)',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Queso gruyère rallado',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pochar las cebollas en mantequilla a fuego muy lento durante al menos 45 minutos, removiendo de vez en cuando, hasta que estén muy doradas y caramelizadas.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el vino blanco y dejar reducir.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar el caldo de carne y cocinar a fuego suave 20 minutos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Repartir la sopa en cazuelitas individuales, cubrir con una rebanada de pan tostado y una generosa capa de queso rallado.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Gratinar en el horno hasta que el queso esté fundido y dorado.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Ratatouille','Guiso de verduras de verano de la Provenza —berenjena, calabacín, pimiento y tomate— cocinadas lentamente con hierbas provenzales.','1 h',60,'Fácil',4,'Francesa','entrante','Corta las verduras en trozos parecidos y cocínalas por etapas según su dureza: así todas quedan en su punto a la vez.','https://upload.wikimedia.org/wikipedia/commons/8/8a/Ratatouille02.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 berenjena',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 calabacines',1);
