INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Tomillo y romero frescos',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cortar todas las verduras en dados de tamaño similar.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sofreír la cebolla y el ajo en aceite de oliva.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el pimiento y cocinar 5 minutos; incorporar la berenjena y el calabacín, cocinar otros 10 minutos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el tomate troceado y las hierbas frescas.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocinar a fuego lento, tapado, removiendo de vez en cuando, durante 30-40 minutos hasta que todas las verduras estén muy tiernas.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Quiche lorraine','Tarta salada de masa quebrada rellena de una crema de huevo, nata y panceta, especialidad de la región de Lorena.','1 h',60,'Fácil',6,'Francesa','entrante','Hornea la base de masa sola unos minutos antes de rellenarla (horneado en blanco): evita que quede cruda por debajo.','https://live.staticflickr.com/7454/16345559297_d5c8702610_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 base de masa quebrada',0);
