INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 huevos',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 ml de nata líquida',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Nuez moscada, sal, pimienta',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Queso gruyère rallado (opcional)',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Forrar un molde con la masa quebrada y pinchar el fondo con un tenedor.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dorar la panceta en una sartén sin nada de grasa añadida, y repartirla sobre la base de masa.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Batir los huevos con la nata, la nuez moscada, sal y pimienta.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Verter esta mezcla sobre la panceta y espolvorear con queso rallado si se desea.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hornear a 180 °C 30-35 minutos hasta que esté cuajada y dorada por encima.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Coq au vin','Pollo guisado lentamente en vino tinto con champiñones, cebollitas y panceta, plato clásico de la Borgoña.','1 h 30 min',90,'Media',4,'Francesa','principal','Usa un vino tinto de calidad razonable para cocinar: su sabor se concentra mucho durante la cocción, así que uno malo se notará en el plato.','https://upload.wikimedia.org/wikipedia/commons/7/75/Coq_au_Vin_6of7_%288735164745%29.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 pollo troceado',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de panceta en dados',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 g de champiñones',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 g de cebollitas pequeñas',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 ml de vino tinto',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharada de harina',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Tomillo, laurel',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dorar la panceta en una olla y reservar; en la misma grasa, dorar el pollo por todos lados y reservar.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sofreír las cebollitas y los champiñones en la misma olla.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Espolvorear con harina y remover; añadir el vino tinto poco a poco, raspando el fondo de la olla.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Devolver el pollo y la panceta a la olla, añadir tomillo y laurel, y cocinar tapado a fuego lento 1 hora hasta que el pollo esté muy tierno.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Destapar los últimos 10 minutos para que la salsa reduzca y espese ligeramente.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Boeuf bourguignon','Guiso de ternera cocinada muy lentamente en vino tinto de Borgoña con champiñones y cebollitas, uno de los grandes clásicos franceses.','2 h 30 min',150,'Media',6,'Francesa','principal','Cuanto más lenta y larga sea la cocción, más se deshace la carne: no tengas prisa con este guiso, gana de un día para otro.','https://upload.wikimedia.org/wikipedia/commons/5/53/Boeuf_bourguignon_servi_avec_des_p%C3%A2tes.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 kg de ternera para guisar',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de panceta en dados',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla, 2 zanahorias',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'750 ml de vino tinto',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 g de champiñones',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 g de cebollitas pequeñas',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Tomillo, laurel, harina',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dorar la panceta y reservar; dorar la ternera por tandas en la misma grasa y reservar.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sofreír la cebolla y la zanahoria, espolvorear con harina y remover.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el vino tinto poco a poco, raspando el fondo, y devolver la carne y la panceta a la olla junto con tomillo y laurel.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocinar tapado a fuego muy lento 2 horas, hasta que la carne esté muy tierna.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir los champiñones y las cebollitas salteadas aparte los últimos 20-30 minutos.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Cassoulet','Guiso denso de alubias blancas con confit de pato, salchicha y panceta, cocinado muy lentamente en cazuela de barro, del suroeste de Francia.','2 h 30 min',150,'Alta',6,'Francesa','principal','Romper y dejar que se reforme la costra dorada de pan varias veces durante el horneado es el paso tradicional que da al cassoulet su textura característica.','https://upload.wikimedia.org/wikipedia/commons/a/a5/Bowl_of_cassoulet.JPG','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 g de alubias blancas (en remojo)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 muslos de confit de pato',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 g de salchicha de Toulouse o similar',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de panceta',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla, 2 dientes de ajo',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Tomate triturado, pan rallado',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocer las alubias remojadas con la cebolla y el ajo hasta que estén tiernas, reservando el caldo.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dorar la panceta y la salchicha en una cazuela de barro.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el confit de pato desmenuzado y un poco de tomate triturado.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar las alubias cocidas y su caldo, mezclar con cuidado.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cubrir con pan rallado y hornear a 160 °C al menos 1 hora, rompiendo la costra que se forma en la superficie un par de veces y dejando que se vuelva a formar.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Confit de pato','Muslos de pato cocinados muy lentamente sumergidos en su propia grasa hasta quedar tiernísimos, y después dorados hasta la piel crujiente.','3 h + reposo',180,'Media',4,'Francesa','principal','La grasa debe cocinar el pato a fuego muy bajo, sin apenas burbujear: un hervor fuerte reseca la carne en vez de dejarla tierna.','https://upload.wikimedia.org/wikipedia/commons/6/60/Confitdecanard.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 muslos de pato',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal gruesa, tomillo, laurel',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Grasa de pato (suficiente para cubrir)',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Ajo',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Frotar los muslos de pato con sal gruesa, tomillo, laurel y ajo, y dejar macerar en la nevera al menos 12 horas.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Enjuagar el exceso de sal y secar bien.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sumergir los muslos en grasa de pato derretida en una cazuela, y cocinar a fuego muy bajo, casi sin burbujear, durante 2-3 horas hasta que estén muy tiernos.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar enfriar los muslos dentro de la grasa (pueden conservarse así varios días).',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Para servir, dorar los muslos en una sartén caliente, con la piel hacia abajo, hasta que quede crujiente.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Bouillabaisse','Guiso marinero de varios pescados y mariscos con azafrán, típico de Marsella, servido con una salsa rouille y pan tostado.','1 h',60,'Alta',6,'Francesa','principal','Añade los distintos pescados y mariscos por tandas, empezando por los que necesitan más cocción: así ninguno queda pasado ni crudo.','https://upload.wikimedia.org/wikipedia/commons/2/24/Bullabessa.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1,5 kg de pescados variados de roca',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 g de mejillones o gambas',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla, 1 puerro, 2 tomates',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Hinojo, azafrán, piel de naranja',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva, ajo',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Pan tostado y salsa rouille (mayonesa con ajo y azafrán)',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sofreír la cebolla, el puerro y el hinojo en aceite de oliva.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el tomate, el azafrán y la piel de naranja, cocinar unos minutos.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cubrir con agua o caldo de pescado y cocinar 20 minutos para hacer un caldo con mucho sabor.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Colar si se desea un caldo más limpio, y devolver al fuego; añadir los pescados y mariscos en tandas según el tiempo de cocción de cada uno.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir el caldo y el pescado por separado, acompañados de pan tostado untado con salsa rouille.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Steak frites con salsa bearnesa','Entrecot a la plancha acompañado de patatas fritas finas y una salsa bearnesa cremosa de mantequilla, huevo y estragón.','40 min',40,'Media',4,'Francesa','principal','Bate la salsa bearnesa siempre al baño maría y sin prisa: el calor directo hace que las yemas cuajen en vez de emulsionar.','https://upload.wikimedia.org/wikipedia/commons/9/9a/Reel_and_Brand_-_September_2021_-_Sarah_Stierch_05.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 entrecots',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Patatas para freír',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'3 yemas de huevo',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de mantequilla clarificada',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Vinagre de estragón, chalota, estragón fresco',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cortar las patatas en bastones finos y freírlas en dos tandas (primero a menor temperatura, después a fuego fuerte para dorar) hasta que estén crujientes.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Reducir el vinagre con la chalota picada y el estragón hasta casi evaporarse.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Batir las yemas al baño maría con esta reducción hasta que espesen, e ir incorporando la mantequilla clarificada poco a poco hasta emulsionar.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Asar los entrecots a la plancha al punto deseado y dejar reposar unos minutos.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir la carne con las patatas fritas y la salsa bearnesa aparte.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Salade niçoise','Ensalada fría de atún, huevo cocido, judía verde, tomate y aceitunas negras, especialidad de Niza.','25 min',25,'Fácil',4,'Francesa','principal','No mezcles los ingredientes: la salade niçoise tradicional se presenta en montoncitos separados sobre la fuente, no revuelta.','https://upload.wikimedia.org/wikipedia/commons/7/7f/Salade_ni%C3%A7oise.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 g de atún en conserva de calidad',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 huevos cocidos',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 g de judía verde',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 tomates',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceitunas negras de Niza',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Anchoas, aceite de oliva, vinagre',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocer las judías verdes hasta que estén tiernas pero firmes, y enfriar en agua con hielo.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocer los huevos y cortarlos en cuartos.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Disponer en una fuente el tomate en gajos, las judías verdes, el atún desmigado, los huevos y las aceitunas.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir unas anchoas por encima.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Aliñar con aceite de oliva y un poco de vinagre justo antes de servir.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Croque monsieur','Sándwich de pan de molde con jamón y queso gruyère, cubierto con bechamel y gratinado al horno.','25 min',25,'Fácil',4,'Francesa','principal','Usa una bechamel bien espesa: si queda demasiado líquida, se escurre del sándwich al gratinar en vez de formar una costra dorada.','https://upload.wikimedia.org/wikipedia/commons/3/3e/Croque_monsieur.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'8 rebanadas de pan de molde',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'4 lonchas de jamón cocido',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de queso gruyère rallado',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'20 g de mantequilla, 20 g de harina, 250 ml de leche (bechamel)',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Mostaza (opcional)',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Preparar una bechamel espesa derritiendo la mantequilla, añadiendo la harina y luego la leche poco a poco hasta espesar.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Untar las rebanadas de pan con un poco de mostaza si se desea, y montar los sándwiches con el jamón y parte del queso.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cubrir la superficie de cada sándwich con bechamel y espolvorear con el resto del queso.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Gratinar en el horno hasta que el queso esté fundido y dorado.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Crêpes suzette','Crepes finas flambeadas en una salsa de mantequilla, azúcar y zumo de naranja, clásico de la repostería francesa de sala.','40 min',40,'Media',4,'Francesa','postre','Deja reposar la masa de crepes antes de cocinarla: el gluten se relaja y las crepes quedan más finas y elásticas.','https://live.staticflickr.com/2317/2220655887_dc1f2dd752_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'200 g de harina',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'3 huevos',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 ml de leche',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Mantequilla',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 naranjas',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'100 g de azúcar',5);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Licor de naranja (opcional)',6);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Batir la harina, los huevos y la leche hasta obtener una masa fina y sin grumos; dejar reposar 20 minutos.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocinar crepes finas en una sartén ligeramente engrasada, doradas por ambos lados.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Derretir mantequilla con azúcar en una sartén amplia hasta que empiece a caramelizar.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el zumo de naranja y dejar reducir a una salsa brillante.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sumergir las crepes dobladas en la salsa, calentar bien y, si se desea, flambear con un chorro de licor de naranja.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Tarte tatin','Tarta de manzana invertida, caramelizada primero en la sartén y cubierta después con masa quebrada antes de hornear.','1 h',60,'Media',6,'Francesa','postre','Desmolda la tarta mientras aún está caliente, volteándola de golpe sobre el plato: si se enfría, el caramelo se solidifica y se pega al molde.','https://live.staticflickr.com/7274/7553092598_509ce63fe0_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'6-8 manzanas ácidas (tipo reineta)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de azúcar',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'80 g de mantequilla',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 base de masa quebrada',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Pelar y cortar las manzanas en cuartos u octavos.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Derretir el azúcar en una sartén apta para horno hasta obtener un caramelo dorado, añadir la mantequilla y remover.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Colocar las manzanas apretadas sobre el caramelo, con el lado curvo hacia abajo.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cocinar a fuego medio unos minutos hasta que las manzanas empiecen a ablandarse.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cubrir con la masa quebrada, remetiendo los bordes hacia dentro, y hornear a 200 °C 25-30 minutos; desmoldar volteando sobre un plato mientras aún está caliente.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Crème brûlée','Crema de vainilla horneada al baño maría, con una fina costra de azúcar caramelizada que se rompe con la cuchara.','50 min + refrigeración',50,'Media',4,'Francesa','postre','Caramelizar el azúcar justo antes de servir, nunca con antelación: si se hace demasiado pronto, la costra se reblandece con la humedad de la crema.','https://upload.wikimedia.org/wikipedia/commons/d/dc/Cr%C3%A8me_br%C3%BBl%C3%A9e_%284554822506%29.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 ml de nata para montar',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 vaina de vainilla',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'5 yemas de huevo',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'80 g de azúcar',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Azúcar extra para caramelizar',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Calentar la nata con las semillas de la vaina de vainilla, sin dejar que hierva.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Batir las yemas con el azúcar hasta blanquear ligeramente.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Verter la nata caliente sobre las yemas poco a poco, removiendo sin parar para que no cuajen de golpe.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Repartir en moldes individuales y cocinar al baño maría en el horno a 150 °C durante 30-35 minutos, hasta que estén cuajadas pero aún tiemblen ligeramente en el centro.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Refrigerar varias horas y, justo antes de servir, espolvorear con azúcar y caramelizar con un soplete de cocina.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Macarons','Pequeños dulces de almendra molida y merengue, crujientes por fuera y tiernos por dentro, rellenos de ganache o mermelada.','1 h + reposo',60,'Alta',6,'Francesa','postre','No te saltes el reposo antes de hornear: la costra que se forma en la superficie es lo que permite que los macarons desarrollen su característico \'pie\' al cocerse.','https://upload.wikimedia.org/wikipedia/commons/d/d1/Macarons_Marcolini_04.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de almendra molida fina',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de azúcar glas',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'3 claras de huevo',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'150 g de azúcar',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Colorante alimentario (opcional)',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Ganache de chocolate o mermelada (para el relleno)',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Tamizar la almendra molida con el azúcar glas.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Montar las claras a punto de nieve, añadiendo el azúcar poco a poco hasta obtener un merengue firme y brillante.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Incorporar la mezcla de almendra al merengue con movimientos envolventes, hasta lograr una textura que caiga en forma de cinta (el \'macaronage\').',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Formar pequeños discos con manga pastelera sobre papel de horno, golpear la bandeja para eliminar burbujas de aire y dejar reposar 30-40 minutos hasta que se forme una fina costra al tacto.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hornear a 150 °C 12-14 minutos; dejar enfriar por completo y rellenar de dos en dos con ganache o mermelada.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Francesa','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Hummus casero','Puré cremoso de garbanzos, tahini, limón y ajo, el mojo levantino más extendido del Mediterráneo.','15 min',15,'Fácil',4,'Mediterránea','entrante','Tritura los garbanzos varios minutos más de lo que parece necesario: cuanto más tiempo, más fino y sedoso queda el hummus.','https://live.staticflickr.com/7178/6815671096_63735fe071_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'400 g de garbanzos cocidos',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'3 cucharadas de tahini',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 diente de ajo',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Zumo de 1 limón',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Comino, sal, pimentón para decorar',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Triturar los garbanzos con el tahini, el ajo, el zumo de limón y un poco de agua fría hasta obtener una textura muy fina.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir sal y comino al gusto, y seguir triturando hasta que quede completamente cremoso.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Ajustar la textura con más agua fría si queda demasiado espeso.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir en un plato hondo, con un chorro de aceite de oliva y una pizca de pimentón por encima.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mediterránea','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Baba ganoush','Puré de berenjena asada con tahini, ajo y limón, con un característico aroma ahumado.','40 min',40,'Fácil',4,'Mediterránea','entrante','Asar la berenjena directamente sobre la llama, aunque se ensucie por fuera, es lo que da al baba ganoush su aroma ahumado característico.','https://live.staticflickr.com/3806/13117795964_f0b75bfc89_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 berenjenas grandes',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 cucharadas de tahini',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 diente de ajo',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Zumo de limón',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Perejil, sal',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Asar las berenjenas enteras directamente sobre la llama o en el horno muy caliente hasta que la piel esté completamente quemada y la pulpa muy tierna.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar templar y retirar toda la piel quemada, escurriendo el exceso de líquido de la pulpa.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Triturar o machacar la pulpa junto con el tahini, el ajo y el zumo de limón.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Sazonar con sal, servir con un chorro de aceite de oliva y perejil picado por encima.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mediterránea','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Muhammara','Paté de pimientos asados, nueces y melaza de granada, con un punto picante, típico de la cocina siria.','30 min',30,'Fácil',4,'Mediterránea','entrante','Tuesta ligeramente las nueces antes de triturarlas: potencia mucho su sabor frente a usarlas crudas.','https://upload.wikimedia.org/wikipedia/commons/4/4c/Tanoreen_muhammara.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'3 pimientos rojos asados',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'100 g de nueces',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 diente de ajo',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharada de melaza de granada',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Pan rallado o migas de pan',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Comino, chile en polvo, aceite de oliva',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Asar los pimientos hasta que la piel esté ampollada, pelarlos y retirar las semillas.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Triturar los pimientos con las nueces, el ajo, la melaza de granada y las especias hasta obtener una pasta con textura.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir un poco de pan rallado si queda demasiado líquido, para espesar.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Ajustar de sal y aceite de oliva, y servir a temperatura ambiente.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mediterránea','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Tapenade de aceitunas negras','Pasta untable de aceitunas negras, alcaparras y anchoas, típica de la Provenza francesa y muy extendida en toda la costa mediterránea.','10 min',10,'Fácil',4,'Mediterránea','entrante','No añadas sal sin probar antes: las aceitunas, las anchoas y las alcaparras ya aportan mucha por sí solas.','https://upload.wikimedia.org/wikipedia/commons/6/61/Cuillere_de_tapenade.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'250 g de aceitunas negras deshuesadas',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 filetes de anchoa',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cucharada de alcaparras',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 diente de ajo',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Zumo de limón',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Triturar las aceitunas, las anchoas, las alcaparras y el ajo hasta obtener una pasta con algo de textura.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir aceite de oliva poco a poco mientras se tritura, hasta lograr la consistencia deseada.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Terminar con un chorro de zumo de limón.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir sobre pan tostado o como acompañamiento de verduras crudas.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mediterránea','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Labneh con aceite de oliva y za\'atar','Yogur colado hasta obtener una textura de queso cremoso, servido con aceite de oliva y la mezcla de especias za\'atar.','15 min + colado',15,'Fácil',4,'Mediterránea','entrante','Cuanto más tiempo cueles el yogur, más firme quedará el labneh: para una textura casi de queso, deja colar hasta 48 horas.','https://upload.wikimedia.org/wikipedia/commons/2/2c/Labneh01.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 g de yogur natural griego',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Za\'atar (mezcla de tomillo, sésamo y zumaque)',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Pan de pita para acompañar',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Mezclar el yogur con una pizca de sal.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Verter en un paño limpio o gasa fina colocado sobre un colador, y dejar escurrir en la nevera al menos 12-24 horas, hasta que quede muy espeso.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Formar una bola o extender en un plato hondo formando un hueco en el centro.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Rociar generosamente con aceite de oliva y espolvorear con za\'atar.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Servir con pan de pita templado.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mediterránea','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Falafel','Bolitas fritas de garbanzo crudo triturado con hierbas y especias, crujientes por fuera y verdes por dentro.','40 min + remojo',40,'Media',4,'Mediterránea','entrante','Usa siempre garbanzos crudos en remojo, nunca cocidos: los garbanzos cocidos tienen demasiada agua y el falafel se deshace al freír.','https://upload.wikimedia.org/wikipedia/commons/5/5b/Falafel_beim_Isarinselfest_M%C3%BCnchen_2.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'300 g de garbanzos secos, en remojo 12 horas (no cocidos)',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolla, 2 dientes de ajo',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Perejil y cilantro frescos',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Comino, cilantro molido',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Bicarbonato, sal',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite para freír',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Escurrir bien los garbanzos remojados (deben usarse crudos, nunca cocidos).',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Triturar los garbanzos con la cebolla, el ajo, las hierbas y las especias hasta obtener una masa con textura granulada, no un puré fino.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir una pizca de bicarbonato y dejar reposar la masa 30 minutos en la nevera.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Formar pequeñas bolas u óvalos con las manos.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Freír en aceite bien caliente hasta que estén doradas y crujientes por fuera.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mediterránea','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Tabulé (tabbouleh)','Ensalada libanesa de perejil picado muy fino, bulgur, tomate y menta, aliñada con limón y aceite de oliva.','30 min',30,'Fácil',4,'Mediterránea','entrante','En el tabulé auténtico el perejil es el protagonista y el bulgur es secundario: usa mucha más hierba que grano.','https://live.staticflickr.com/7055/6916828023_c78839510e_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'50 g de bulgur fino',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 manojos grandes de perejil fresco picado muy fino',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Menta fresca picada',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 tomates en dados pequeños',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 cebolleta',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Zumo de limón, aceite de oliva virgen extra',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Remojar el bulgur en agua fría o templada 15-20 minutos hasta que esté tierno, y escurrir bien.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Picar el perejil muy fino, a cuchillo, junto con la menta y la cebolleta.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Mezclar las hierbas picadas con el tomate en dados y el bulgur escurrido.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Aliñar generosamente con zumo de limón, aceite de oliva y sal justo antes de servir.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mediterránea','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Fattoush','Ensalada libanesa de verduras frescas y pan de pita tostado, aliñada con melaza de granada y sumac.','20 min',20,'Fácil',4,'Mediterránea','entrante','Añade el pan tostado en el último momento: si se mezcla con antelación, absorbe el aliño y pierde el punto crujiente.','https://upload.wikimedia.org/wikipedia/commons/9/93/Fattoush_mixed-salad.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 panes de pita',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 tomates, 1 pepino',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 pimiento verde, rábanos',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Lechuga, cebolleta, menta fresca',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Zumo de limón, melaza de granada, sumac, aceite de oliva',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Tostar los panes de pita en el horno o en una sartén hasta que estén crujientes, y trocearlos en pedazos irregulares.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cortar todas las verduras en trozos de tamaño similar y mezclar en una fuente grande.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Preparar el aliño mezclando zumo de limón, melaza de granada, sumac y aceite de oliva.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el pan tostado y el aliño justo antes de servir, mezclando bien.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mediterránea','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Ensalada de garbanzos con feta','Ensalada fresca de garbanzos, pepino, tomate y queso feta, aliñada con aceite de oliva y orégano.','15 min',15,'Fácil',4,'Mediterránea','entrante','Añade el feta al final y con cuidado: se desmorona con facilidad si se mezcla con demasiada fuerza.','https://live.staticflickr.com/7620/17102801921_e892f20d4c_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'400 g de garbanzos cocidos',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 pepino, 2 tomates',1);
