INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Orégano seco, aceite de oliva virgen extra, zumo de limón',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Escurrir bien los garbanzos cocidos.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cortar el pepino y el tomate en dados y mezclar con los garbanzos.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Añadir el feta en dados y las aceitunas.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Aliñar con aceite de oliva, zumo de limón y orégano al gusto justo antes de servir.',3);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mediterránea','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Boquerones en vinagre','Filetes de boquerón fresco marinados en vinagre y aceite de oliva con ajo y perejil, tapa fría típica de toda la costa mediterránea española.','20 min + 24 h de marinado',1460,'Fácil',4,'Mediterránea','entrante','Congela siempre el pescado antes de marinarlo en crudo: es una medida de seguridad alimentaria imprescindible, no un paso opcional.','https://upload.wikimedia.org/wikipedia/commons/5/50/Boquerones_en_vinagre-Madrid.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'500 g de boquerones frescos, limpios en filetes',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Vinagre de vino blanco',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Agua',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Sal',3);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Ajo picado, perejil fresco picado',4);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra',5);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Congelar los boquerones limpios al menos 48 horas antes de prepararlos, por seguridad frente al anisakis, y descongelar en la nevera.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Colocar los filetes en un recipiente y cubrir con una mezcla a partes iguales de vinagre y agua con un poco de sal.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar marinar en la nevera entre 6 y 12 horas, hasta que la carne esté blanca por completo.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Escurrir bien el líquido de marinado, colocar en una fuente con ajo y perejil picados, y cubrir con aceite de oliva.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Dejar reposar al menos un par de horas en la nevera antes de servir.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mediterránea','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Berenjenas fritas con miel de caña','Bastones de berenjena rebozados y fritos hasta quedar crujientes, servidos con un chorro de miel de caña, tapa típica de Andalucía.','25 min',25,'Fácil',4,'Mediterránea','entrante','Sirve las berenjenas nada más freírlas: pierden el crujiente muy rápido si se dejan reposar demasiado.','https://commons.wikimedia.org/wiki/Special:FilePath/Berenjenas%20rebozadas%20con%20salmorejo.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'2 berenjenas',0);
