INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pan con tomate catalán','Pan de pueblo tostado, frotado con tomate maduro y ajo, y aliñado con aceite de oliva y sal, la base de cualquier desayuno catalán.','10 min',10,'Fácil',4,'Mediterránea','entrante','Usa siempre tomates muy maduros, casi pasados: cuanto más blandos, más fácil es frotarlos y más sabor sueltan en el pan.','https://upload.wikimedia.org/wikipedia/commons/8/8a/Pa_amb_tomaquet.jpg','base');
