INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Shakshuka','Huevos escalfados sobre una salsa especiada de tomate y pimiento, plato de desayuno o cena muy extendido por todo el Mediterráneo oriental.','30 min',30,'Fácil',4,'Mediterránea','principal','Cocina los huevos siempre tapados y a fuego suave: así cuajan por vapor de forma uniforme sin necesidad de darles la vuelta.','https://upload.wikimedia.org/wikipedia/commons/2/26/Shakshuka1.jpg','base');
