INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Kibbeh','Croquetas alargadas de bulgur y carne picada especiada, rellenas de más carne, fritas hasta quedar crujientes.','1 h',60,'Alta',4,'Mediterránea','principal','Moja las manos con agua fría al trabajar la masa de bulgur: se vuelve pegajosa y es mucho más fácil de moldear así.','https://upload.wikimedia.org/wikipedia/commons/5/5c/%C4%B0%C3%A7li_k%C3%B6fte.png','base');
