INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Halloumi a la plancha','Queso chipriota de textura firme, marcado a la plancha hasta dorar, con un chorro de limón y hierbas.','10 min',10,'Fácil',4,'Mediterránea','principal','Sirve el halloumi inmediatamente después de la plancha: al enfriarse pierde parte de su textura característica y se vuelve gomoso.','https://live.staticflickr.com/7397/9507158023_a840c32fd8_b.jpg','base');
