INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Imam bayildi (berenjenas rellenas turcas)','Berenjenas enteras rellenas de cebolla, tomate y ajo, cocinadas lentamente en aceite de oliva hasta quedar melosas.','1 h',60,'Media',4,'Mediterránea','principal','No escatimes en el aceite de oliva: este plato se cocina prácticamente confitado, y es lo que le da su textura melosa característica.','https://upload.wikimedia.org/wikipedia/commons/7/7b/%C4%B0mam_bay%C4%B1ld%C4%B1_AvL.JPG','base');
