INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Paella valenciana','Arroz cocinado en paellera con pollo, conejo y verduras, sazonado con azafrán, el plato de arroz más emblemático de España.','1 h',60,'Media',6,'Mediterránea','principal','No remuevas el arroz una vez repartido en la paellera: dejarlo quieto es lo que permite que se forme el socarrat en el fondo.','https://upload.wikimedia.org/wikipedia/commons/e/ed/01_Paella_Valenciana_original.jpg','base');
