INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Dorada a la sal','Pescado entero cubierto con una costra de sal gruesa y horneado, técnica que mantiene toda la jugosidad del pescado.','45 min',45,'Fácil',4,'Mediterránea','principal','No escames el pescado antes de cocinarlo: la piel y las escamas protegen la carne del exceso de sal durante el horneado.','https://live.staticflickr.com/3243/3017843692_537583fe76_b.jpg','base');
