INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Mezclar la sal gruesa con las claras de huevo si se desea una costra más compacta.',0);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Cubrir la base de una bandeja de horno con una capa de sal, colocar el pescado entero encima y cubrirlo completamente con el resto de la sal, presionando bien.',1);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hornear a 200 °C unos 30-35 minutos, calculando aproximadamente 12-15 minutos por cada kilo de pescado.',2);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Romper la costra de sal en la mesa, retirar con cuidado y limpiar los restos antes de servir.',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Aliñar con un buen aceite de oliva virgen extra y unas gotas de limón.',4);
INSERT INTO receta_etiquetas (receta_id,etiqueta,tipo) VALUES (@rid,'Mediterránea','libre');
INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Lubina al horno con hierbas provenzales','Lubina entera horneada con tomate, hierbas provenzales y un buen chorro de aceite de oliva.','35 min',35,'Fácil',4,'Mediterránea','principal','Cocina la lubina sobre una cama de verdura y hierbas: además de aromatizar el pescado, evita que se pegue a la bandeja.','https://live.staticflickr.com/2144/1526986088_9ec878fb14_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'1 lubina grande entera, limpia',0);
