INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva virgen extra, sal',4);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Hacer unos cortes diagonales en los lomos de la lubina y salarla por dentro y por fuera.',0);
