INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Sardinas rellenas al horno','Sardinas abiertas en libro y rellenas de pan rallado, piñones y hierbas, horneadas hasta quedar doradas.','35 min',35,'Media',4,'Mediterránea','principal','Pide en la pescadería que te abran las sardinas \'en libro\', sin separar los dos lomos: así se rellenan y cierran con mucha más facilidad.','https://live.staticflickr.com/2607/4228116293_61bf2426e2_b.jpg','base');
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'16 sardinas frescas, limpias y abiertas en libro',0);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Pan rallado, piñones tostados',1);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Ajo y perejil picados',2);
INSERT INTO receta_ingredientes (receta_id,texto,orden) VALUES (@rid,'Aceite de oliva, limón',3);
INSERT INTO receta_pasos (receta_id,texto,orden) VALUES (@rid,'Mezclar el pan rallado con los piñones tostados, el ajo y el perejil picados, y un chorro de aceite de oliva.',0);
