INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Gazpacho andaluz','Sopa fría de tomate, pepino, pimiento y ajo triturados con aceite de oliva, el refresco vegetal por excelencia del verano andaluz.','15 min + frío',15,'Fácil',4,'Mediterránea','postre','Usa siempre tomates muy maduros y de temporada: son la base del sabor del gazpacho y no hay truco que compense un tomate mediocre.','https://upload.wikimedia.org/wikipedia/commons/c/c0/Gazpacho_Cazuela_Barro.jpg','base');
