INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Salmorejo cordobés','Crema fría y espesa de tomate y pan, más densa que el gazpacho, servida con huevo duro y jamón picados por encima.','20 min + frío',20,'Fácil',4,'Mediterránea','postre','La proporción de pan es lo que diferencia el salmorejo del gazpacho: debe quedar mucho más denso, casi para untar.','https://upload.wikimedia.org/wikipedia/commons/e/eb/Salmorejo_cordobes.jpg','base');
