INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pisto manchego','Fritada de verduras de La Mancha —calabacín, pimiento, cebolla y tomate— cocinada lentamente hasta quedar melosa.','1 h',60,'Fácil',4,'Mediterránea','postre','Cocina el pisto a fuego lento y con paciencia: cuanto más tiempo, mejor se integran los sabores de las verduras.','https://upload.wikimedia.org/wikipedia/commons/9/93/Pisto.jpg','base');
