INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pan de pita casero','Pan plano que se hincha en el horno formando una bolsa hueca, base de innumerables platos del Mediterráneo oriental.','1 h 30 min (con reposo)',90,'Media',4,'Mediterránea','postre','Precalienta bien la bandeja o piedra de horno antes de meter los panes: el choque de calor inicial es lo que hace que se hinchen.','https://upload.wikimedia.org/wikipedia/commons/3/32/Pita_Bread.jpg','base');
