INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Pilaf de bulgur con verduras','Bulgur salteado con verduras y especias suaves, guarnición habitual en toda la cocina del Mediterráneo oriental.','30 min',30,'Fácil',4,'Mediterránea','postre','Tuesta siempre el bulgur en el sofrito antes de añadir el líquido: potencia mucho su sabor frente a cocerlo directamente en el caldo.','https://upload.wikimedia.org/wikipedia/commons/a/a3/Bulgur.jpg','base');
