INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Sandwich mixto','Pan de molde con jamón cocido y queso, tostado en sartén o sandwichera hasta que el queso funde.','10 min',10,'Fácil',2,'Fácil y casera','principal','Presiona ligeramente el sandwich mientras se tuesta: ayuda a que se dore de manera uniforme y a que el queso funda antes.','https://upload.wikimedia.org/wikipedia/commons/5/58/File-Sand._Mixto_-_Extra_queso_%28detalle%29.jpg','base');
