INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Natillas caseras','Crema dulce de huevo y leche, cocinada en el cazo, el postre casero español de toda la vida.','20 min + frío',20,'Fácil',4,'Fácil y casera','postre','No dejes que hierva una vez añadidas las yemas: si hierve con fuerza, se pueden cortar y quedar grumosas.','https://upload.wikimedia.org/wikipedia/commons/c/c1/Bowl_of_natillas_at_Madrid.jpg','base');
