INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Arroz con leche','Postre cremoso de arroz cocido lentamente en leche con azúcar, canela y piel de limón.','50 min',50,'Fácil',4,'Fácil y casera','postre','Remueve con frecuencia durante toda la cocción: es lo que evita que se pegue al fondo y ayuda a que suelte el almidón para quedar cremoso.','https://upload.wikimedia.org/wikipedia/commons/b/ba/Arroz_con_leche.png','base');
