INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Macedonia de frutas','Mezcla fresca de frutas de temporada troceadas, con un chorrito de zumo de naranja, el postre más ligero de todos.','15 min',15,'Fácil',4,'Fácil y casera','postre','Añade el plátano en dados al final y remuévelo con suavidad: es la fruta que más rápido se oscurece y se deshace si se mezcla en exceso.','https://upload.wikimedia.org/wikipedia/commons/7/74/Fruktsallad_%28Fruit_salad%29.jpg','base');
