INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Galletas de mantequilla','Galletas caseras crujientes con solo cuatro ingredientes básicos, listas para hornear en media hora.','35 min',35,'Fácil',6,'Fácil y casera','postre','Deja enfriar las galletas sobre la propia bandeja unos minutos antes de moverlas: recién salidas del horno están muy frágiles y se rompen con facilidad.','https://live.staticflickr.com/7436/8726079227_8ab0c2dbbf_b.jpg','base');
