INSERT INTO recetas (titulo,descripcion,tiempo,tiempo_min,dificultad,raciones_base,cocina,plato,consejo,photo_url,origen) VALUES ('Brownie de chocolate fácil','Bizcocho denso y húmedo de chocolate, con una costra ligeramente crujiente por encima, listo en menos de una hora.','45 min',45,'Fácil',8,'Fácil y casera','postre','Sácalo del horno un poco antes de lo que parezca necesario: el brownie sigue cuajando fuera del horno y debe quedar jugoso en el centro.','https://live.staticflickr.com/2603/4009689469_87f65c9bdc_b.jpg','base');
